INSERT INTO public.recipes (title, description, ingredients, instructions, garnish, method, category, imageurl) VALUES
('Whisky Sour', 'A combinação perfeita de destilado, cítrico e doçura, com uma textura sedosa.', '[{"name":"Bourbon (Whiskey)","measure":"60 ml"},{"name":"Suco de Limão Siciliano","measure":"30 ml"},{"name":"Xarope Simples","measure":"15 ml"},{"name":"Clara de Ovo","measure":"15 ml (Opcional)"},{"name":"Angostura Aromatic Bitters","measure":"2 dashes"}]', '["Adicione todos os ingredientes na coqueteleira.","Faça o \"Dry Shake\" (bater sem gelo) para emulsificar a clara.","Adicione gelo e bata vigorosamente.","Coe para um copo baixo com gelo."]', 'Twist de laranja e cereja', 'Batido', 'Clássico', '/uploads/recipes/whisky-sour.jpg'),
('Daiquiri', 'Um clássico cubano injustiçado. Quando bem feito, é fresco, complexo e revigorante.', '[{"name":"Rum Branco","measure":"60 ml"},{"name":"Suco de Limão","measure":"30 ml"},{"name":"Xarope Simples","measure":"15 ml"}]', '["Adicione todos os ingredientes na coqueteleira com gelo.","Bata vigorosamente até a coqueteleira gelar bem.","Coe duplamente para uma taça coupette gelada."]', 'Twist de limão', 'Batido', 'Clássico', '/uploads/recipes/Daiquiri.jpg'),
('Margarita', 'O drink de Tequila mais famoso do mundo. Ácido, salgado e vibrante.', '[{"name":"Tequila Blanco ou Prata","measure":"50 ml"},{"name":"Cointreau (Triple Sec)","measure":"30 ml"},{"name":"Suco de Limão","measure":"20 ml"}]', '["Passe um limão na borda da taça e cruste com sal.","Bata todos os ingredientes na coqueteleira com gelo.","Coe para a taça preparada com ou sem gelo novo."]', 'Roda de limão e borda de sal', 'Batido', 'Clássico', '/uploads/recipes/margarita.jpg'),
('Jungle Bird', 'Um Tiki Drink raro que usa Campari. Rico e agridoce.', '[{"name":"Rum Escuro","measure":"45 ml"},{"name":"Campari","measure":"20 ml"},{"name":"Suco de Abacaxi","measure":"45 ml"},{"name":"Suco de Limão","measure":"15 ml"},{"name":"Xarope Simples","measure":"15 ml"}]', '["Bata vigorosamente com gelo.","Coe para um copo baixo com gelo novo."]', 'Fatia de abacaxi', 'Batido', 'Alcoólico', '/uploads/recipes/Jungle-Bird.jpg'),
('Gimlet', 'Para quem ama Gin e cítricos sem distrações.', '[{"name":"Gin","measure":"60 ml"},{"name":"Lime Cordial (ou suco + açúcar)","measure":"30 ml"}]', '["Bata com gelo e coe para taça coupette."]', 'Fatia de limão', 'Batido', 'Clássico', '/uploads/recipes/gimlet.jpg'),
('Tom Collins', 'Uma limonada turbinada com Gin. Simples e extremamente refrescante.', '[{"name":"Gin","measure":"50 ml"},{"name":"Suco de Limão","measure":"25 ml"},{"name":"Xarope Simples","measure":"20 ml"},{"name":"Água com Gás","measure":"completar"}]', '["Monte no copo alto com gelo.","Mexa levemente."]', 'Fatia de limão e cereja', 'Montado', 'Clássico', '/uploads/recipes/Tom-Collins.jpg'),
('Manhattan', 'O primo sofisticado do Martini feito com Whiskey.', '[{"name":"Whisky Rye ou Bourbon","measure":"60 ml"},{"name":"Vermute Rosso (Doce)","measure":"30 ml"},{"name":"Angostura Bitters","measure":"2 dashes"}]', '["Adicione ingredientes no mixing glass com gelo.","Mexa até gelar bem.","Coe para uma taça martini gelada."]', 'Cereja amarena', 'Mexido', 'Clássico', '/uploads/recipes/manhattan.jpg'),
('Espresso Martini', 'Criado nos anos 80 para \"te acordar e te deixar bêbado\". Cremoso e energético.', '[{"name":"Vodka","measure":"50 ml"},{"name":"Licor de Café (Kahlúa)","measure":"30 ml"},{"name":"Café Espresso","measure":"30 ml"},{"name":"Xarope Simples","measure":"5 ml (opcional)"}]', '["Bata todos os ingredientes vigorosamente com muito gelo.","Coe duplamente para uma taça coupette gelada para garantir a espuma."]', '3 grãos de café', 'Batido', 'Alcoólico', '/uploads/recipes/espresso-martini.jpg'),
('Aperol Spritz', 'O rei do verão europeu. Leve, laranja e borbulhante.', '[{"name":"Aperol","measure":"60 ml"},{"name":"Prosecco, Espumante","measure":"90 ml"},{"name":"Água com Gás","measure":"30 ml"}]', '["Em uma taça de vinho com muito gelo, adicione o Prosecco.","Adicione o Aperol.","Complete com um splash de água com gás.","Mexa levemente."]', 'Fatia de laranja', 'Montado', 'Alcoólico', '/uploads/recipes/Aperol-Spritz.jpg'),
('Negroni', 'Um aperitivo italiano icônico, perfeitamente equilibrado entre amargo, doce e botânico.', '[{"name":"London Dry Gin","measure":"30 ml"},{"name":"Campari","measure":"30 ml"},{"name":"Vermute Rosso (Doce)","measure":"30 ml"}]', '["Adicione todos os ingredientes em um mixing glass com gelo.","Mexa por cerca de 30 segundos para resfriar.","Coe para um copo baixo com um cubo de gelo grande."]', 'Casca de laranja', 'Mexido', 'Clássico', '/uploads/recipes/Negroni.jpg'),
('Moscow Mule', 'Famoso pela canequinha de cobre e pela espuma de gengibre.', '[{"name":"Vodka","measure":"50 ml"},{"name":"Suco de Limão","measure":"20 ml"},{"name":"Ginger Beer (ver Cerveja de Gengibre )","measure":"completar"},{"name":"Espuma Gengibre","measure":"topo"}]', '["Em uma caneca com gelo, adicione a vodka e o limão.","Complete com Ginger Beer.","Mexa suavemente.","Coloque por cima a espuma."]', 'Fatia de limão e hortelã', 'Montado', 'Clássico', '/uploads/recipes/moscow-mule.jpg'),
('Cuba Libre', 'Mais do que Rum e Cola. Um toque de limão transforma tudo.', '[{"name":"Rum Branco ou Ouro","measure":"50 ml"},{"name":"Refrigerante de Cola","measure":"100 ml"},{"name":"Suco de Limão","measure":"10 ml"}]', '["Encha um copo alto com gelo.","Adicione o rum e o suco de limão.","Complete com cola e mexa levemente."]', 'Fatia de limão', 'Montado', 'Alcoólico', '/uploads/recipes/cuba-libre.jpg'),
('Irish Coffee', 'A bebida quente perfeita. Café, whiskey irlandês e creme.', '[{"name":"Whisky Irlandês","measure":"45 ml"},{"name":"Café Quente","measure":"90 ml"},{"name":"Açúcar Mascavo","measure":"1 colher bar"},{"name":"Creme de Leite Batido","measure":"30 ml"}]', '["Aqueça uma taça para café.","Misture o whisky, café e açúcar até dissolver.","Flutue cuidadosamente o creme de leite por cima."]', 'Noz-moscada (opcional)', 'Montado', 'Alcoólico', '/uploads/recipes/Irish-Coffee.jpg'),
('Gin & Tonic', 'O drink mais popular do mundo. A qualidade da tônica e do gin fazem toda a diferença.', '[{"name":"London Dry Gin","measure":"50 ml"},{"name":"Água Tônica","measure":"100-150 ml"}]', '["Encha uma taça balloon com muito gelo.","Adicione o gin e complete com a tônica.","Mexa suavemente apenas para misturar."]', 'Rodela de limão ou pepino', 'Montado', 'Clássico', '/uploads/recipes/Gin-tonica.jpg'),
('Dry Martini', 'A elegância em forma de drink. Gin gelado com um toque sutil de vermute seco.', '[{"name":"Gin London Dry","measure":"60 ml"},{"name":"Vermute Dry","measure":"10 ml"}]', '["Adicione o gin e o vermute em um mixing glass com muito gelo.","Mexa vigorosamente por 45 segundos.","Coe duplamente para uma taça martini previamente gelada."]', 'Azeitona ou twist de limão siciliano', 'Mexido', 'Clássico', '/uploads/recipes/dry-martini.jpg'),
('Sazerac', 'O drink oficial de New Orleans. Parente próximo do Old Fashioned com absinto.', '[{"name":"Cognac ou Rye Whiskey","measure":"60 ml"},{"name":"Absinto","measure":"1 dash (rinse)"},{"name":"Cubo de Açúcar","measure":"1 unidade"},{"name":"Peychauds Bitters","measure":"4 dashes"}]', '["Banhe um copo baixo com absinto e descarte o excesso.","Em outro copo, macere açúcar e bitters, adicione gelo e destilado.","Mexa e coe para o copo banhado com absinto (sem gelo)."]', 'Casca de limão', 'Mexido', 'Clássico', '/uploads/recipes/sazerac.jpg'),
('Bloody Mary', 'O drink perfeito para o brunch ou para curar a ressaca. Salgado e temperado.', '[{"name":"Vodka","measure":"50 ml"},{"name":"Suco de Tomate","measure":"100 ml"},{"name":"Suco de Limão","measure":"15 ml"},{"name":"Molho Inglês","measure":"2 dashes"},{"name":"Tabasco","measure":"à gosto"},{"name":"Sal e Pimenta","measure":"pitada"}]', '["Role os ingredientes no mixing glass com gelo (não bata para não diluir o tomate).","Coe para copo alto com gelo."]', 'Talo de salsão', 'Mexido', 'Alcoólico', '/uploads/recipes/bloody-mary.jpg'),
('Bramble', 'Gin sour com licor de amora. Frutado e visualmente lindo.', '[{"name":"Gin","measure":"50 ml"},{"name":"Suco de Limão","measure":"25 ml"},{"name":"Xarope de Açúcar","measure":"15 ml"},{"name":"Licor de Amora","measure":"15 ml"}]', '["Bata gin, limão e açúcar.","Coe para copo baixo com gelo picado.","Despeje o licor de amora sobre o gelo para criar o efeito \"bleeding\"."]', 'Amoras e limão', 'Montado', 'Clássico', '/uploads/recipes/bramble.jpg'),
('Boulevardier', 'O Negroni feito com Bourbon. Mais rico, quente e outonal.', '[{"name":"Bourbon","measure":"45 ml"},{"name":"Campari","measure":"30 ml"},{"name":"Vermute Rosso (Doce)","measure":"30 ml"}]', '["Mexa com gelo no mixing glass.","Coe para copo baixo com gelo ou taça coupette."]', 'Casca de laranja', 'Mexido', 'Clássico', '/uploads/recipes/Boulevardier.jpg'),
('Paloma', 'Mais popular que a Margarita no México. Tequila e toranja (grapefruit).', '[{"name":"Tequila Blanco ou Prata","measure":"50 ml"},{"name":"Suco de Limão","measure":"15 ml"},{"name":"Refrigerante de Toranja (Grapefruit)","measure":"completar"},{"name":"Sal","measure":"pitada"}]', '["Monte no copo alto com gelo."]', 'Fatia de toranja', 'Montado', 'Alcoólico', '/uploads/recipes/paloma.jpg'),
('Mai Tai', 'O rei dos drinks Tiki. Complexo, forte e com sabor de amêndoas.', '[{"name":"Rum Envelhecido","measure":"40 ml"},{"name":"Rum Branco","measure":"20 ml"},{"name":"Suco de Limão","measure":"30 ml"},{"name":"Cointreau (Triple Sec)","measure":"15 ml"},{"name":"Xarope de Amêndoas","measure":"15 ml"}]', '["Bata todos os ingredientes com muito gelo.","Coe para um copo baixo com gelo novo (triturado preferencialmente)."]', 'Ramo de hortelã e fatia de limão', 'Batido', 'Alcoólico', '/uploads/recipes/mai-tai.jpg'),
('Dark \''n\'' Stormy', 'Rum escuro e Ginger Beer. Simples e picante.', '[{"name":"Rum Escuro","measure":"60 ml"},{"name":"Ginger Beer (ver Cerveja de Gengibre )","measure":"100 ml"},{"name":"Suco de Limão","measure":"15 ml"}]', '["Encha copo alto com gelo e ginger beer.","Adicione o limão.","Flutue o rum escuro no topo."]', 'Fatia de limão', 'Montado', 'Alcoólico', '/uploads/recipes/Dark-n-Stormy.jpg'),
('Clover Club', 'Um clássico pré-lei seca. Gin, framboesa e clara de ovo.', '[{"name":"Gin","measure":"45 ml"},{"name":"Xarope de Framboesa","measure":"15 ml"},{"name":"Suco de Limão","measure":"15 ml"},{"name":"Clara de Ovo","measure":"1 unidade"}]', '["Dry shake.","Bata com gelo.","Coe para taça coupette."]', '3 framboesas', 'Batido', 'Clássico', '/uploads/recipes/clover-club.jpg'),
('French 75', 'Nomeado após uma arma da 1ª Guerra Mundial, porque bate forte como uma.', '[{"name":"Gin","measure":"30 ml"},{"name":"Suco de Limão Siciliano","measure":"15 ml"},{"name":"Xarope Simples","measure":"15 ml"},{"name":"Brütt, Espumante","measure":"Completar"}]', '["Bata gin, limão e açúcar com gelo.","Coe para taça flute.","Complete com espumante."]', 'Twist de limão', 'Batido', 'Clássico', '/uploads/recipes/French75.jpg'),
('Penicillin', 'Um clássico moderno. Scotch, limão, mel e gengibre, com um toque defumado.', '[{"name":"Blended Scotch","measure":"50 ml"},{"name":"Suco de Limão","measure":"20 ml"},{"name":"Xarope de Mel e Gengibre","measure":"20 ml"},{"name":"Islay Whisky (Defumado)","measure":"10 ml (topo)"}]', '["Bata os primeiros 3 ingredientes com gelo.","Coe para copo baixo com gelo novo.","Flutue o whisky defumado no topo."]', 'Gengibre cristalizado', 'Batido', 'Clássico', '/uploads/recipes/penicillin.jpg'),
('Cosmopolitan', 'Popularizado por Sex and the City, é um clássico moderno frutado e seco.', '[{"name":"Vodka Citron","measure":"40 ml"},{"name":"Cointreau (Triple Sec)","measure":"15 ml"},{"name":"Suco de Limão","measure":"15 ml"},{"name":"Suco de Cranberry","measure":"30 ml"}]', '["Bata tudo com gelo na coqueteleira.","Coe para taça martini."]', 'Twist de laranja', 'Batido', 'Clássico', '/uploads/recipes/cosmopolitan.jpg'),
('Caipiroska', 'A versão da caipirinha com Vodka. Suave e popular', '[{"name":"Vodka","measure":"60 ml"},{"name":"Limão Taiti","measure":"1 unidade"},{"name":"Açúcar","measure":"2 colheres bar"}]', '["Macere o limão com açúcar no copo baixo.","Adicione gelo e a vodka.","Mexa bem."]', 'Fatia de limão', 'Montado', 'Alcoólico', '/uploads/recipes/caipiroska.jpg'),
('Caipirinha', 'O drink nacional do Brasil. Simplicidade genial', '[{"name":"Cachaça","measure":"60 ml"},{"name":"Limão Taiti","measure":"1 unidade"},{"name":"Açúcar","measure":"2 colheres bar"}]', '["Corte o limão em cubos ou fatias.","Macerar o limão com o açúcar no copo.","Adicione gelo e a cachaça.","Mexa bem."]', 'Fatia de limão', 'Montado', 'Clássico', '/uploads/recipes/caipirinha.jpeg'),
('Mimosa', 'O drink oficial do café da manhã.', '[{"name":"Suco de Laranja","measure":"75 ml"},{"name":"Brütt, Espumante","measure":"75 ml"}]', '["Sirva o suco na taça flute.","Complete com espumante."]', 'Nenhum', 'Montado', 'Alcoólico', '/uploads/recipes/Mimosa.jpg'),
('Old Fashioned', 'O coquetel original. Whiskey, açúcar e bitters. Simples, forte e atemporal.', '[{"name":"Whisky Bourbon ou Rye","measure":"60 ml"},{"name":"Cubo de Açúcar","measure":"1 unidade"},{"name":"Angostura Bitters","measure":"3 dashes"},{"name":"Água","measure":"1 lance"}]', '["Coloque o cubo de açúcar no copo e molhe com os bitters e a água.","Amasse o açúcar até dissolver.","Adicione gelo grande e o whisky.","Mexa suavemente para gelar e diluir."]', 'Casca de laranja e cereja luxardo', 'Mexido', 'Clássico', '/uploads/recipes/Old-Fashioned.jpg'),
('Long Island Iced Tea', 'Parece chá gelado, mas contém 5 destilados diferentes.', '[{"name":"Vodka","measure":"15 ml"},{"name":"Rum","measure":"15 ml"},{"name":"Gin","measure":"15 ml"},{"name":"Tequila","measure":"15 ml"},{"name":"Triple Sec","measure":"15 ml"},{"name":"Suco de Limão","measure":"25 ml"},{"name":"Coca-Cola","measure":"Completar"}]', '["Bata os destilados e limão com gelo.","Coe para copo alto com gelo.","Complete com cola."]', 'Limão', 'Batido', 'Alcoólico', '/uploads/recipes/Long-Island-Iced-Tea2.jpg'),
('Piña Colada', 'Se você gosta de tomar chuva... O clássico tropical de Porto Rico.', '[{"name":"Rum Branco","measure":"50 ml"},{"name":"Leite de Coco","measure":"30 ml"},{"name":"Suco de Abacaxi","measure":"50 ml"}]', '["Bata todos os ingredientes com gelo no liquidificador para versão frozen, ou na coqueteleira.","Sirva em um copo longo (Hurricane)."]', 'Fatia de abacaxi e cereja', 'Batido', 'Alcoólico', '/uploads/recipes/pina-colada.jpeg'),
('Zombie', 'Um drink Tiki potente criado para \"ressuscitar os mortos\". Cuidado.', '[{"name":"Mix de Rums (Branco/Escuro)","measure":"60 ml"},{"name":"Suco de Limão","measure":"30 ml"},{"name":"Suco de Toranja","measure":"30 ml"},{"name":"Xarope de Canela","measure":"15 ml"},{"name":"Grenadine","measure":"1 dash"}]', '["Bata com gelo e sirva em copo alto ou Tiki Mug."]', 'Hortelã e frutas', 'Batido', 'Alcoólico', '/uploads/recipes/zombie.jpg'),
('Pisco Sour', 'O clássico Andino (Peru/Chile). Cítrico, doce e com espuma cremosa.', '[{"name":"Pisco","measure":"60 ml"},{"name":"Suco de Limão","measure":"30 ml"},{"name":"Xarope Simples","measure":"20 ml"},{"name":"Clara de Ovo","measure":"1 unidade"},{"name":"Angostura Bitters","measure":"3 gotas (final)"}]', '["Dry shake (sem gelo) para emulsificar.","Bata com gelo.","Coe para copo baixo.","Pingue o bitter sobre a espuma."]', 'Gotas de Angostura', 'Batido', 'Alcoólico', '/uploads/recipes/pisco-sour.jpg'),
('Mojito', 'Refrescante coquetel cubano perfeito para dias quentes.', '[{"name":"Rum Branco","measure":"50 ml"},{"name":"Suco de Limão","measure":"25 ml"},{"name":"Xarope de Açúcar","measure":"15 ml"},{"name":"Hortelã","measure":"8-10 folhas"},{"name":"Água com gás","measure":"Completar"}]', '["Em um copo alto, macere levemente a hortelã com o suco de limão e xarope.","Adicione o rum e encha o copo com gelo triturado.","Complete com água com gás e mexa delicadamente."]', 'Ramo de hortelã', 'Montado', 'Clássico', '/uploads/recipes/Mojito.jpg'),
('Vesper Martini', 'Inventado por James Bond em Casino Royale.', '[{"name":"Gin","measure":"60 ml"},{"name":"Vodka","measure":"20 ml"},{"name":"Lillet Blanc","measure":"10 ml"}]', '["Bata com gelo (como Bond pede) ou mexa (tradicional).","Coe para taça martini."]', 'Twist de limão siciliano', 'Batido', 'Clássico', '/uploads/recipes/Vesper-martini.jpg'),
('White Russian', 'O favorito do \"The Dude\". Vodka, café e creme.', '[{"name":"Vodka","measure":"50 ml"},{"name":"Licor de Café","measure":"20 ml"},{"name":"Creme de Leite fresco","measure":"30 ml"}]', '["Monte a vodka e licor no copo com gelo.","Flutue o creme por cima."]', 'Grãos de Café', 'Montado', 'Clássico', '/uploads/recipes/white-russian.jpg'),
('Sidecar', 'O melhor drink de conhaque. cítrico, seco e sofisticado.', '[{"name":"Cognac","measure":"50 ml"},{"name":"Cointreau","measure":"20 ml"},{"name":"Suco de Limão","measure":"20 ml"}]', '["Bata com gelo e coe.","Sirva em taça com borda de açúcar (opcional)."]', 'Twist de laranja', 'Batido', 'Clássico', '/uploads/recipes/sidecar.jpg'),
('Aviation', 'Um clássico floral e azulado (se usar creme de violeta).', '[{"name":"Gin","measure":"45 ml"},{"name":"Maraschino","measure":"15 ml"},{"name":"Suco de Limão","measure":"15 ml"},{"name":"Creme de Violeta","measure":"1 colher bar (opcional)"}]', '["Bata com gelo e coe."]', 'Cereja', 'Batido', 'Clássico', '/uploads/recipes/Aviation.jpg'),
('Mint Julep', 'O drink oficial do Kentucky Derby. Bourbon, hortelã e muito gelo.', '[{"name":"Bourbon","measure":"60 ml"},{"name":"Hortelã","measure":"8 folhas"},{"name":"Açúcar","measure":"1 colher bar"}]', '["Macere levemente a hortelã com açúcar.","Encha o copo (de metal) com gelo triturado.","Adicione o bourbon e mexa até o copo suar."]', 'Ramo de hortelã', 'Montado', 'Clássico', '/uploads/recipes/Mint-Julep.jpg'),
('Michelada', 'O drink de cerveja mexicano. Refrescante, salgado e picante.', '[{"name":"Cerveja Lager","measure":"330 ml"},{"name":"Suco de Limão","measure":"30 ml"},{"name":"Molho de Pimenta","measure":"3 dashes"},{"name":"Molho Inglês","measure":"3 dashes"},{"name":"Sal e Tajin","measure":"borda"}]', '["Cruste a borda do copo com sal e Tajin.","Adicione gelo, limão e molhos.","Complete com a cerveja."]', 'Fatia de limão', 'Montado', 'Alcoólico', '/uploads/recipes/michelada.jpg'),
('Tequila Sunrise', 'Um degradê lindo que lembra o nascer do sol.', '[{"name":"Tequila","measure":"45 ml"},{"name":"Suco de Laranja","measure":"90 ml"},{"name":"Xarope de Grenadine","measure":"15 ml"}]', '["Tequila e laranja no copo com gelo.","Despeje o grenadine devagar para ir ao fundo."]', 'Cereja e laranja', 'Montado', 'Alcoólico', '/uploads/recipes/tequila-sunrise.jpg'),
('Kir Royale', 'Um aperitivo francês chique e simples.', '[{"name":"Creme de Cassis","measure":"15 ml"},{"name":"Champagne / Espumante","measure":"Completar"}]', '["Cassis no fundo da taça flute.","Complete com espumante."]', 'Mirtilo ou amora', 'Montado', 'Alcoólico', '/uploads/recipes/Kir-Royal.jpg'),
('Bellini', 'Criado no Harry\''s Bar em Veneza. Purê de pêssego e Prosecco.', '[{"name":"Purê de Pêssego","measure":"50 ml"},{"name":"Prosecco, Espumante","measure":"100 ml"}]', '["Coloque o purê na taça flute.","Complete suavemente com Prosecco gelado."]', 'Fatia de pêssego', 'Montado', 'Alcoólico', '/uploads/recipes/Bellini.jpg'),
('Bee\''s Knees', 'Um clássico da Era do Jazz. Gin, limão e mel. Simples e dourado.', '[{"name":"Gin","measure":"60 ml"},{"name":"Suco de Limão Siciliano","measure":"25 ml"},{"name":"Xarope de Mel","measure":"20 ml"}]', '["Dissolva o mel no suco ou use xarope.","Bata com gelo.","Coe para taça coupette."]', 'Twist de limão', 'Batido', 'Clássico', '/uploads/recipes/bees-knees.jpg'),
('Southside', 'O \"Mojito de Gin\", favorito de Al Capone.', '[{"name":"Gin","measure":"60 ml"},{"name":"Limão Taiti","measure":"30 ml"},{"name":"Xarope Simples","measure":"15 ml"},{"name":"Hortelã","measure":"6-8 folhas"}]', '["Bata todos os ingredientes com gelo.","Coe duplamente para uma taça coupette."]', 'Folha de hortelã', 'Batido', 'Clássico', '/uploads/recipes/southside.jpg'),
('Paper Plane', 'Bourbon, Amaro e Aperol em partes iguais. Equilíbrio perfeito.', '[{"name":"Bourbon","measure":"20 ml"},{"name":"Aperol","measure":"20 ml"},{"name":"Amaro Nonino","measure":"20 ml"},{"name":"Suco de Limão Siciliano","measure":"20 ml"}]', '["Bata tudo com gelo.","Coe para taça coupette."]', 'Mini avião de papel (opcional)', 'Batido', 'Clássico', '/uploads/recipes/paper-plane.jpg'),
('Sex on the Beach', 'Doce, frutado e a cara dos anos 80.', '[{"name":"Vodka","measure":"40 ml"},{"name":"Licor de Pêssego","measure":"20 ml"},{"name":"Suco de Laranja","measure":"40 ml"},{"name":"Suco de Cranberry","measure":"40 ml"}]', '["Bata tudo com gelo.","Coe para copo alto com gelo."]', 'Laranja e cereja', 'Batido', 'Clássico', '/uploads/recipes/sex-on-the-beach.jpg'),
('Fitzgerald', 'Um Gin Sour moderno com Angostura. Simplesmente delicioso.', '[{"name":"Gin","measure":"60 ml"},{"name":"Suco de Limão","measure":"25 ml"},{"name":"Xarope de Açúcar","measure":"20 ml"},{"name":"Angostura Bitters","measure":"3 dashes"}]', '["Bata tudo com gelo.","Coe para copo baixo com gelo."]', 'Twist de limão', 'Batido', 'Clássico', '/uploads/recipes/fitzgerald.jpg'),
('Gin Basil Smash', 'Verde, herbal e incrivelmente fresco. Um clássico moderno alemão.', '[{"name":"Gin","measure":"60 ml"},{"name":"Manjericão Fresco","measure":"12 folhas"},{"name":"Suco de Limão","measure":"25 ml"},{"name":"Xarope de Açúcar","measure":"20 ml"}]', '["Macere o manjericão com limão na coqueteleira.","Adicione gin, açúcar e gelo.","Bata vigorosamente.","Coe duplamente para remover pedaços de folha."]', 'Ramo de manjericão', 'Batido', 'Alcoólico', '/uploads/recipes/gin-basil-smash.jpg'),
('The Last Word', 'Um clássico esquecido e redescoberto. Herbáceo e potente.', '[{"name":"Gin","measure":"20 ml"},{"name":"Chartreuse Verde","measure":"20 ml"},{"name":"Maraschino","measure":"20 ml"},{"name":"Suco de Limão","measure":"20 ml"}]', '["Bata tudo com gelo.","Coe para taça coupette."]', 'Cereja amarena', 'Batido', 'Clássico', '/uploads/recipes/the-last-word.jpg'),
('Amaretto Sour', 'Doce e azedo na medida certa, com sabor de amêndoas.', '[{"name":"Amaretto","measure":"50 ml"},{"name":"Bourbon","measure":"10 ml"},{"name":"Suco de Limão Siciliano","measure":"30 ml"},{"name":"Clara de Ovo","measure":"1 unidade"}]', '["Dry shake para emulsificar.","Bata com gelo.","Coe para copo baixo com gelo."]', 'Cereja e limão', 'Batido', 'Clássico', '/uploads/recipes/Amaretto_Sour.jpg'),
('Valentine’s Vodka Mojito', 'Um coquetel refrescante para ser feito com a sua vodka favorito.', '[{"name":"Vodka","measure":"60 ml"},{"name":"Limão Taiti","measure":"1 unidade"},{"name":"Morango","measure":"1 unidade"},{"name":"Framboesa","measure":"2 unidades"},{"name":"Açúcar Mascavo","measure":"2 colher bar"},{"name":"Hortelã","measure":"5-6 folhas"},{"name":"Club Soda","measure":"60 ml"}]', '["Em um copo alto, coloque o limão, o morango, a framboesa junto com as 2 colheres de açúcar mascavo.","Dê uma leve macerada nestes ingredientes.","Depois coloque as folhas de hortelã e a vodka com bastante gelo picado ou pequenas pedrinhas de gelo.","Coloque o Club Soda ou complete, dando uma leve mexida de baixo para cima para misturar tudo."]', 'Meio morango na borda do copo, e um ramo de hortelã.', 'Montado', 'Alcoólico', '/uploads/recipes/Valentine-s-Vodka-Mojito.jpg'),
('Tequila Sunrise Mimosa', 'É uma variação potente e colorida da clássica mimosa, ideal para ocasiões especiais. ', '[{"name":"Tequila Blanco ou Prata","measure":"60 ml"},{"name":"Suco de Limão Taiti","measure":"15 ml"},{"name":"Suco de Laranja","measure":"60 ml"},{"name":"Prosecco, Espumante","measure":"Completar"},{"name":"Xarope de Grenadine","measure":"15 ml"}]', '["Num copo longo, acrescente a tequila, o suco de limão, o de laranja,","Complete deixando 1 dedo da borda e acrescente o grenadine levemente."]', 'Rodela de limão desidratado', 'Montado', 'Alcoólico', '/uploads/recipes/tequila-sunrise-mimosa.png'),
('Cranberry Margarita', '', '[{"name":"Tequila","measure":"45 ml"},{"name":"Triple Sec","measure":"22 ml"},{"name":"Suco de Cranberry","measure":"90 ml"},{"name":"Suco de Limão","measure":"15 ml"}]', '["Fazer uma borda de sal marinho umedecendo com limão. Coloque pedras de gelo para gelar o copo e reserve.","Coloque os ingredientes em uma coqueteleira com gelo e bata vigorosamente. Retirar o degelo do copo preparado e coar o coquetel."]', 'Cranberrys e fatia de limão', 'Batido', 'Alcoólico', '/uploads/recipes/Cranberry-Margarita.png'),
('Espanhola versão 2', '', '[{"name":"Vodka","measure":"50 ml"},{"name":"Vinho Tinto Suave","measure":"150 ml"},{"name":"Suco de Abacaxi","measure":"200 ml"},{"name":"Leite Condensado","measure":"40 ml"}]', '["Coloque tudo na coqueteleira com gelo e agite vigorosamente. Depois e só fazer uma coagem simples para não passar o gelo para taça.","Transfira tudo, decore com um pedaço de abacaxi e sirva!!"]', 'Pedaço de abacaxi', 'Batido', 'Alcoólico', '/uploads/recipes/ESPANHOLA-II.png'),
('Freezing Orgasm', '', '[{"name":"Tequila","measure":"50 ml"},{"name":"Suco Limão","measure":"1 unidade"},{"name":"Açúcar","measure":"2 colher bar"},{"name":"Skol Beats 150 bpm","measure":"completar"}]', '["Em uma coqueteleira adicione o Suco de Limão. Depois o açúcar e a tequila coloque gelo e bata.","Depois pegue um copo longo adicione gelo. Com uma peneira coe a mistura para o copo.","Agora é só completar com a skol beats, como inclinada dentro do copo e enquanto beber o drink vai enchendo até acabar."]', '', 'Batido', 'Alcoólico', '/uploads/recipes/freezing-orgasm.jpg'),
('Blue Widow', '', '[{"name":"Vodka","measure":"50 ml"},{"name":"Licor Curaçau Blue","measure":"25 ml"},{"name":"Skol Beats 150 bpm","measure":""}]', '["Na coqueteleira adicione gelo, curaçau blue, Vodka, skol beats e bata bastante até a bem suada a coqueteleira.","Pegue o Leite Condensado e misture com um pouco de corante preto. Coloque num prato e passe a borda da taça (taça gelada no congelador), fazer uma dupla coagem e finalize com uma cereja no fundo da taça."]', 'Cereja', 'Batido', 'Alcoólico', '/uploads/recipes/Blue-Widow.png'),
('Cosmopolitan Versão 2', '', '[{"name":"Vodka","measure":"50 ml"},{"name":"Triple Sec","measure":"25 ml"},{"name":"Suco de Limão","measure":"25 ml"},{"name":"Xarope de Cranberry","measure":"25 ml"}]', '["Coloque os ingredientes na coqueteleira, bata vigorosamente, coe para uma taça tipo dry martini."]', '2 cerejas no palito', 'Batido', 'Alcoólico', '/uploads/recipes/Cosmopolitan-II.png'),
('Acapulco', '', '[{"name":"Tequila","measure":"25 ml"},{"name":"Rum","measure":"25 ml"},{"name":"Suco de Abacaxi","measure":"50 ml"},{"name":"Suco de Laranja","measure":"50 ml"}]', '["Basta colocar todos os ingredientes numa coqueteleira com gelo triturado e bater bem. ","Decore como quiser e está pronto!"]', 'Rodela de limão', 'Batido', 'Alcoólico', '/uploads/recipes/acapulco.png'),
('Arco-Íris', '', '[{"name":"Gin","measure":"30 ml"},{"name":"Vodka","measure":"30 ml"},{"name":"Licor Curaçau Blue","measure":"30 ml"},{"name":"Grenadine","measure":"40 ml"},{"name":"Suco de Laranja","measure":"40 ml"},{"name":"Xarope de Açúcar","measure":"10 ml"}]', '["Em um liquidificador colocar o grenadine e a Vodka e gelo, bater até ficar nevado, adicionar a taça.","O mesmo preparo com o gin e o Suco de Laranja.","E o mesmo com o curaçau e Xarope de Açúcar."]', 'Ramo de hortelã e rodela de laranja', 'Batido', 'Alcoólico', '/uploads/recipes/ARCO-RIS.png'),
('Sea Green', '', '[{"name":"Gin","measure":"60 ml"},{"name":"Cointreau","measure":"25 ml"},{"name":"Licor de Menta","measure":"10 ml"},{"name":"Suco de Limão","measure":"10 ml"},{"name":"Soda Limonada","measure":"completar"}]', '["Em uma coqueteleira adicione todos os ingredientes exceto a soda, bata bastante até resfriar a coqueteleira, passe para um copo longo e adicione a soda."]', '', 'Batido', 'Alcoólico', '/uploads/recipes/SEA-GREEN.png'),
('Sensations', '', '[{"name":"Suco de Manga","measure":"25 ml"},{"name":"Suco de Limão","measure":"15 ml"},{"name":"Xarope de Menta","measure":"10 ml"},{"name":"Suco de Cranberry","measure":"completar"}]', '["Bata o Suco de Manga, Suco de Limão e o Xarope de Menta em uma coqueteleira com os cubos de gelo e sirva em um copo long drink (300 ml).","Complete com Suco de Cranberry.","Essa é a receita original. Existe uma variação alcoólica que adiciona 30ml de Gin."]', 'Ramo de hortelã', 'Batido', 'Sem Álcool', '/uploads/recipes/Sensations.png'),
('Sonho de Anjo', '', '[{"name":"Cachaça","measure":"200 ml"},{"name":"Catuaba","measure":"200 ml"},{"name":"Chambinhos","measure":"2 unidades"},{"name":"Leite em Pó","measure":"3 colheres de sopa"},{"name":"Açúcar","measure":"3 colheres bar"},{"name":"Gelo","measure":"8 pedras grandes"}]', '["Bata tudo no liquidificador e sirva."]', '', 'Batido', 'Alcoólico', '/uploads/recipes/Sonho-de-Anjo.jpg'),
('Acapulco´s Malibu', '', '[{"name":"Malibu","measure":"30 ml"},{"name":"Suco de Manga","measure":"45 ml"}]', '["Junte todos os ingredientes em uma coqueteleira e bata."]', 'Pedaço de manga', 'Batido', 'Alcoólico', '/uploads/recipes/Acapulco-s-Malibu.png'),
('Caipirinha de Morango', '', '[{"name":"Cachaça","measure":"50 ml"},{"name":"Açúcar","measure":"2 colheres bar"},{"name":"Morangos","measure":"5 unidades"}]', '["Bater 2 morangos com um pouco de cachaça no liquidificador,","Depois, cortar o restante dos morangos em pedacinhos pequenos.","Em um copo, misturar os morangos cortados com o suco que foi batido.","Acrescentar o açúcar e a cachaça."]', 'Morangos', 'Batido', 'Alcoólico', '/uploads/recipes/Caipirinha-de-morango.png'),
('Caipirinha de Guaraná', '', '[{"name":"Vodka","measure":"50 ml"},{"name":"Suco de Limão","measure":"3 fatias"},{"name":"Açúcar","measure":"2 colheres bar"},{"name":"Guaraná","measure":"completar"}]', '["Em uma coqueteleira, coloque o limão e o açúcar e macere.","Acrescente gelo, Vodka e agite até ficar bem gelado.","Coloque num copo e complete o restante com guaraná."]', '', 'Batido', 'Alcoólico', '/uploads/recipes/Caipirinha-de-Guaran.png'),
('Café Russo', '', '[{"name":"Vodka","measure":"50 ml"},{"name":"Leite Condensado","measure":"50 ml"},{"name":"Espresso Intenso","measure":"100 ml"}]', '["Quando sobrar café na cafeteira (não pode estar adoçado), coloque em forminhas de gelo e leve ao freezer, deixando congelar.","Coloque no liquidificador o Leite Condensado, a Vodka, e os cubos de café congelado.","Bata por 15 segundos e sirva em copos para coquetel."]', 'Chantilly', 'Batido', 'Alcoólico', '/uploads/recipes/Caf-Russo.png'),
('De Pernas Pro Ar', '', '[{"name":"Vodka","measure":"50 ml"},{"name":"Açúcar","measure":"1 colher bar"},{"name":"Limão","measure":"meio"},{"name":"Leite Condensado","measure":"2 colheres de sopa"}]', '["Coloque em uma coqueteleira: a Vodka, o açúcar, o Leite Condensado, o limão, 4 ou 5 pedras de gelo e bata até ela ficar gelada (suada).","Filtre para um copo com gelo.","Decore com 2 fatias de limão. Se preferir pode dar uma espremida no limão antes de colocar na coqueteleira;"]', 'Rodela de limão', 'Batido', 'Alcoólico', '/uploads/recipes/de-pernas-pro-ar.jpg'),
('Lemon Drop', '', '[{"name":"Vodka","measure":"60 ml"},{"name":"Suco de Limão Siliciano","measure":"22.5 ml"},{"name":"Triple Sec","measure":"7.5 ml"},{"name":"Xarope de Açúcar","measure":"30 ml"}]', '["Adicione gelo à taça ou ponha-a no congelador para resfriá-la.","Adicionar todos ingredientes na coqueteleira.","Bata até gelar o cocktail e sirva com coagem dupla."]', 'Zest de limão siciliano', 'Batido', 'Alcoólico', '/uploads/recipes/LEMON-DROP.jpg'),
('Baby Bellini', '', '[{"name":"Suco de Pêssego","measure":"75 ml"},{"name":"Suco de Limão","measure":"75 ml"},{"name":"Água com Gás","measure":"completar"},{"name":"Suco de Laranja","measure":"completar"}]', '["Resfrie o suco de pêssego e o do limão numa coqueteleira com gelo.","Coe para um copo alto e mexa bem.","Complete com Suco de Laranja e água gaseificada (gelados)."]', '', 'Batido', 'Sem Álcool', '/uploads/recipes/Baby-Bellini.png'),
('Caipirinha Água com Gás', '', '[{"name":"Cachaça","measure":"50 ml"},{"name":"Suco de Limão","measure":"50 ml"},{"name":"Sprite","measure":"100 ml"},{"name":"Água com Gás","measure":"100 ml"}]', '["Bater os ingredientes todos numa coqueteleira e servir bem gelado."]', 'Meias fatias de limão', 'Batido', 'Alcoólico', '/uploads/recipes/Caipirinha-de-agua-com-Gas.jpg'),
('Tokio Tea', '', '[{"name":"Vodka","measure":"15 ml"},{"name":"Rum","measure":"15 ml"},{"name":"Gin","measure":"15 ml"},{"name":"Tequila","measure":"15 ml"},{"name":"Triple Sec","measure":"15 ml"},{"name":"Licor de Melão","measure":"30 ml"}]', '["Coloque todos os ingredientes na coqueteleira e bata bem.","Filtre e sirva em um copo tipo highball (aqueles compridos e mais fininhos) com gelo."]', 'Uma cereja e um pedaço de melão', 'Batido', 'Alcoólico', '/uploads/recipes/Tokio-Tea.jpg'),
('Demônio Azedo', '', '[{"name":"Jack Daniel´s","measure":"60 ml"},{"name":"Licor de Groselha","measure":"30 ml"},{"name":"Suco de Limão","measure":"30 ml"},{"name":"Xarope de Açúcar","measure":"30 ml"}]', '["Coloque todos os ingredientes na coqueteleira, bata por uns 10 segundos e sirva num copo baixo."]', 'Ramo de hortelã, fatia fina de pepino e 2 pimentas vermelhas', 'Batido', 'Alcoólico', '/uploads/recipes/DEMoNIO-AZEDO.png'),
('Amarula Fashion', '', '[{"name":"Amarula","measure":"100 ml"},{"name":"Suco de Maracujá","measure":"150 ml"}]', '["Misture tudo na coqueteleira batendo e sirva num copo long drink."]', 'Uma colher de polpa de maracujá', 'Batido', 'Alcoólico', '/uploads/recipes/Amarula-Fashion.png'),
('Lemon Dry', '', '[{"name":"Whisky","measure":"70 ml"},{"name":"Grenadine","measure":"40 ml"},{"name":"Suco de Limão","measure":"20 ml"},{"name":"Açúcar","measure":"2 colheres bar"}]', '["Bata tudo em uma coqueteleira e coe duas vezes","Sirva em uma taça cocktail (martini)."]', 'Fatia de limão e 2 azeitonas no palito', 'Batido', 'Alcoólico', '/uploads/recipes/Lemon-Dry.jpg'),
('Piña Moclada', '', '[{"name":"Suco de Abacaxi","measure":"200 ml"},{"name":"Leite de Coco","measure":"90 ml"},{"name":"Banana","measure":"meia unidade"}]', '["Coloque a banana, o Suco de Abacaxi e o Leite de Coco no liquidificador.","Bata até a mistura ficar homogênea e cremosa.","Despeje no copo com gelo até a metade."]', 'Uma cereja e uma fatia de abacaxi num palitinho', 'Batido', 'Sem Álcool', '/uploads/recipes/Pina-Moclada.jpg'),
('Kamikaze', '', '[{"name":"Vodka","measure":"25 ml"},{"name":"Triple Sec","measure":"25 ml"},{"name":"Suco de Limão","measure":"25 ml"}]', '["Adicione todos os ingredientes em uma coqueteleira.","Mexa e coe o conteúdo em uma taça."]', '1/2 Rodela de limão', 'Batido', 'Alcoólico', '/uploads/recipes/KAMIKAZE.jpg'),
('Viagra', '', '[{"name":"Vodka","measure":"50 ml"},{"name":"Licor Curaçau Blue","measure":"70 ml"},{"name":"Leite Condensado","measure":"70 ml"}]', '["Numa coqueteleira com gelo, coloque todos os ingredientes, agite bem, passe tudo para um copo de sua preferência e pronto!"]', '', 'Batido', 'Alcoólico', '/uploads/recipes/VIAGRA.jpg'),
('Sonho de Valsa', '', '[{"name":"Cachaça","measure":"300 ml"},{"name":"Bombons (sonho de valsa)","measure":"3 unidades"},{"name":"Leite Condensado","measure":"1 lata"},{"name":"Guaraná","measure":"1 lata"}]', '["Bata tudo no liquidificador, deixando os chocolates por último para ficar a parte crocante por cima.","Sirva gelado","Sirva em long drink e sirva com canudinho largo, para não entupir com os pedacinhos de chocolates."]', '', 'Batido', 'Alcoólico', '/uploads/recipes/Sonho-de-valsa.jpg'),
('Witches Brew Blue', '', '[{"name":"Vodka","measure":"30 ml"},{"name":"Licor Curaçau Blue","measure":"15 ml"},{"name":"Suco de Limão","measure":"15 ml"},{"name":"Corante Azul","measure":"pitada"}]', '["Preparar a borda em uma taça, colocar pedras de gelo e reservar. Bater os ingredientes em uma coqueteleira com gelo. Retirar o gelo e degelo da taça reservada e coar o coquetel."]', '', 'Batido', 'Alcoólico', '/uploads/recipes/Witches-Brew-Blue.jpg'),
('Lime, Lemon and Ginger', '', '[{"name":"Vodka","measure":"40 ml"},{"name":"Triple Sec","measure":"20 ml"},{"name":"Suco de Limão Siciliano","measure":"20 ml"},{"name":"Suco de Limão","measure":"20 ml"},{"name":"Xarope de Gengibre","measure":"20 ml"}]', '["Adicionar os ingredientes em uma coqueteleira com bastante gelo e bater. Coar duplamente para um copo alto com gelo e finalizar com twist de limão."]', '', 'Batido', 'Alcoólico', '/uploads/recipes/Lime-Lemon-and-Ginger.jpg'),
('Pineapple Champagne Margarita', '', '[{"name":"Cointreau","measure":"15 ml"},{"name":"Suco de Limão","measure":"15 ml"},{"name":"Abacaxi","measure":"3 pedaços"},{"name":"Espumante Brutt","measure":"completar"}]', '["Macerar o abacaxi com Suco de Limão em uma coqueteleira. Adicionar a tequila, o cointreau, gelo e bater o coquetel. Coar duplamente para uma taça previamente gelada e completar com espumante."]', '', 'Batido', 'Alcoólico', '/uploads/recipes/Pineapple-Champagne-Margarita.jpg'),
('Cilantro Matador', '', '[{"name":"Tequila Reposado","measure":"45 ml"},{"name":"Suco de Limão","measure":"15 ml"},{"name":"Suco de Abacaxi","measure":"60 ml"}]', '["Adicionar os ingredientes em uma coqueteleira com gelo e agitar brevemente. ","Coar duplamente para um copo old fashioned com gelo. ","Guarnecer com folhas da coroa do abacaxi e folhas de coentro."]', 'Folhas da coroa do abacaxi e folhas de coentro', 'Batido', 'Alcoólico', '/uploads/recipes/Cilantro-Matador.png'),
('Paradise', '', '[{"name":"Rum Prata","measure":"50 ml"},{"name":"Licor Curaçau Blue","measure":"50 ml"},{"name":"Xarope de Açúcar","measure":"50 ml"},{"name":"Suco de Laranja","measure":"150 ml"}]', '["Primeiro em uma coqueteleira macerar os morangos juntos com o xarope de açúcar, coloque no copo, adicione gelo por cima, adicione o Suco de Laranja bem lentamente para não misturar, na coqueteleira adicione o rum e o curaçau blue, misture bastante, adicione ao copo lentamente."]', '1 cereja e ramo de alecrim', 'Batido', 'Alcoólico', '/uploads/recipes/PARADISE.jpg'),
('Passionfruit Margarita', '', '[{"name":"Tequila Reposado","measure":"45 ml"},{"name":"Cointreau","measure":"15 ml"},{"name":"Suco de Limão","measure":"60 ml"},{"name":"Xarope de Maracujá","measure":"10 ml"},{"name":"Polpa de Maracujá","measure":"1 colher sopa"}]', '["Adicionar os ingredientes em uma coqueteleira com bastante gelo e agitar bem. ","Servir em um copo e completar com gelo. Decorar com um ramo de hortelã."]', 'Ramo de hortelã', 'Batido', 'Alcoólico', '/uploads/recipes/Passionfruit-Margarita.jpg'),
('The Kanaloa Ku', '', '[{"name":"Gin","measure":"40 ml"},{"name":"Triple Sec","measure":"20 ml"},{"name":"Suco de Limão","measure":"20 ml"},{"name":"Licor Curaçau Blue","measure":"20 ml"},{"name":"Suco de Cranberry","measure":"40 ml"}]', '["Coloque o Suco de Cranberry no fundo de um copo com bastante gelo. ","Bata os demais ingredientes em uma coqueteleira com gelo e coe duplamente para o copo preparado anteriormente. ","Decore com uma fatia de limão desidratada."]', 'Fatia de limão desidratada', 'Batido', 'Alcoólico', '/uploads/recipes/The-Kanaloa-Ku.jpg'),
('Yellow Blue Martini', '', '[{"name":"Gin","measure":"50 ml"},{"name":"Triple Sec","measure":"30 ml"},{"name":"Suco de Laranja","measure":"60 ml"},{"name":"Licor Curaçau Blue","measure":"10 ml"}]', '["Misture o gin, Suco de Laranja e o licor em uma coqueteleira com gelo.","Sirva num copo martini em seguida acrescente o curaçau blue de uma pequena mexida com a bailarina para obter o degrade."]', '', 'Batido', 'Alcoólico', '/uploads/recipes/yellow-blue-Martini.jpg'),
('Wine Mentol', '', '[{"name":"Vodka","measure":"70 ml"},{"name":"Vinho Branco","measure":"50 ml"},{"name":"Licor de Menta","measure":"20 ml"}]', '["Na coqueteleira macere um pequeno cacho de uva verde, após isso coloque a Vodka, vinho, gelo e chacoalhe.","Coloque o licor de menta no fundo do copo, encha a taça de gelo e coloque devagar o líquido da coqueteleira. ","Com uma colher bailarina misture lentamente."]', 'Cacho pequeno de uva verde', 'Batido', 'Alcoólico', '/uploads/recipes/WINE-MENTOL.jpg'),
('Capiroska de Limãranja', '', '[{"name":"Vodka","measure":"75 ml"},{"name":"Açúcar","measure":"1 colher bar"},{"name":"Limão","measure":"1 unidade"},{"name":"Suco de Laranja","measure":"meia unidade"}]', '["Macere o limão com açúcar na coqueteleira, adicione o suco da laranja, gelo e a Vodka. Chacoalhe bastante.","No copo coloque gelo e peneire a mistura.","Experimente ver se está bom de açúcar e de Vodka."]', 'Fatia de laranja desidratada', 'Batido', 'Alcoólico', '/uploads/recipes/CAIPIROSCA-DE-LIMaRANJA.png'),
('Mentol', '', '[{"name":"Vodka","measure":"25 ml"},{"name":"Licor de Menta","measure":"50 ml"},{"name":"Creme de Leite","measure":"100 ml"},{"name":"Leite Condensado","measure":"100 ml"},{"name":"Red Bull","measure":"completar"}]', '["Na coqueteleira ou liquidificador, misture o gelo, licor de menta, Leite Condensado, Creme de Leite e a Vodka.","Misture até ficar bem líquido.","Para montar, use uma taça longa, coando o drink e colocando a mistura até a metade. Complete com o energético."]', '', 'Batido', 'Alcoólico', '/uploads/recipes/MENTOL.jpg'),
('Green Passion', '', '[{"name":"Rum blanco","measure":"60 ml"},{"name":"Licor Curaçau Blue","measure":"50 ml"},{"name":"Suco de Laranja","measure":"completar"}]', '["Adicione todos os ingredientes na coqueteleira e agite bem.","Transfira para um copo e sirva!!","Lembrando que as medidas do Suco de Laranja e curaçau blue variam bastante de copo para copo, cada um tem sua medida para chegar na cor."]', '', 'Batido', 'Alcoólico', '/uploads/recipes/GREEN-PASSION.png'),
('Caipirinha de Laranja', '', '[{"name":"Cachaça","measure":"50 ml"},{"name":"Laranja","measure":"1 unidade"},{"name":"Açúcar","measure":"2 colheres bar"}]', '["Em uma coqueteleira pique a laranja.","Com um macerador amasse a laranja com o açúcar e misture a cachaça, coloque o gelo, misture bem.","Coloque em um copo, decore e sirva!!"]', '', 'Batido', 'Alcoólico', '/uploads/recipes/CAIPIRINHA-DE-LARANJA.png'),
('Caipilé', '', '[{"name":"Cachaça","measure":"50 ml"},{"name":"Morangos","measure":"5 unidades"},{"name":"Açúcar","measure":"2 colhes bar"},{"name":"Picolé Fruta","measure":"1 unidade"}]', '["Pique os morangos, coloque numa coqueteleira e adicione o açúcar.","Macere a fruta junto com o açúcar, sem pressa. Acrescente o destilado escolhido, com o gelo e agite bem.","Na taça, coloque o picolé e acrescente o líquido."]', '', 'Batido', 'Alcoólico', '/uploads/recipes/Caipile.png'),
('Caipirango', '', '[{"name":"Vodka","measure":"50 ml"},{"name":"Açúcar","measure":"1 colher bar"},{"name":"Morangos Maduros","measure":"6 unidades"},{"name":"Água com Gás","measure":"completar"}]', '["Em uma coqueteleira coloque os morangos, adicione a açúcar e macere bem.","Acrescente o gelo e logo em seguida a Vodka.","Chacoalhe bem e sirva em um copo de sua escolha, caso necessário acrescente água gaseificada para dar aquela refrescância ao seu drink."]', '', 'Batido', 'Alcoólico', '/uploads/recipes/Caipirango.png'),
('Caipivinho', '', '[{"name":"Vinho Tinto Suave","measure":"100 ml"},{"name":"Vodka","measure":"75 ml"},{"name":"Limão","measure":"1 unidade"},{"name":"Açúcar","measure":"2 colheres bar"}]', '["Tem duas opções de montagem:","1° coloque tudo dentro da coqueteleira e bata,","2° faça uma caipirinha tradicional coloque na taça, depois coloque o vinho por cima desta forma ambos não se misturam por completo!"]', 'faça uma decoração de sua preferência!', 'Batido', 'Alcoólico', '/uploads/recipes/Caipivinho.png'),
('Caipirinha Limão com Menta', '', '[{"name":"Cachaça","measure":"100 ml"},{"name":"Licor de Menta","measure":"10 ml"},{"name":"Açúcar","measure":"2 colheres bar"},{"name":"Limão","measure":"1 unidade"}]', '["Macere o limão cortado em 4 fatias na coqueteleira, coloque a cachaça e duas colheres de açúcar.","Adicione gelo na coqueteleira e agite bem.","Coloque no copo e com a colher bailarina coloque licor de menta bem devagar."]', '', 'Batido', 'Alcoólico', '/uploads/recipes/caipirinha-de-limao-com-menta.png'),
('Frozen Skol Beats', '', '[{"name":"Skol Beats Senses","measure":"1 unidade"},{"name":"Suco de Limão","measure":"1 unidade"},{"name":"Leite Condensado","measure":"meia caixa"}]', '["Em um liquidificador adicione os ingredientes com gelo, bata até ficar cremoso (frozen)."]', '', 'Batido', 'Alcoólico', '/uploads/recipes/FROZEN-SKOL-BEATS.png'),
('Purple Break', '', '[{"name":"Gin","measure":"25 ml"},{"name":"Licor Curaçau Blue","measure":"25 ml"},{"name":"Grenadine","measure":"15 ml"},{"name":"Suco de Limão","measure":"15 ml"},{"name":"Água Tônica","measure":"completar"}]', '["Em uma coqueteleira adicione os ingredientes com gelo, menos a água tônica, abale bastante até resfriar a coqueteleira, estirpe em uma taça de gin com gelo, complete com a água tônica, guarnição flor de violeta comestível."]', 'Flor de violeta (comestível)', 'Batido', 'Alcoólico', '/uploads/recipes/Purple-break.png'),
('Caipirinha de Maracujá', '', '[{"name":"Cachaça","measure":"50 ml"},{"name":"Xarope de Açúcar","measure":"20 ml"},{"name":"Maracujá","measure":"1 unidade"},{"name":"Suco de Limão","measure":"meio"}]', '["Em uma coqueteleira adicione a polpa do maracujá e o Xarope de Açúcar, macerar para a polpa soltar do caroço, adicione o suco do limão, gelo e a cachaça, abale bastante até resfriar a coqueteleira, estirpe em um copo."]', '', 'Batido', 'Alcoólico', '/uploads/recipes/Caipirinha-de-maracuja.png'),
('Blue Orange', '', '[{"name":"Suco de Laranja","measure":"80 ml"},{"name":"Licor Curaçau Blue","measure":"80 ml"},{"name":"Vodka","measure":"30 ml"},{"name":"Água Tônica Sabor Limão","measure":"completar"}]', '["Coloque 4 cubos de gelo em uma coqueteleira junto com a Vodka, Suco de Laranja e curaçau blue, misture bem.","Em uma taça, coloque algumas pedras de gelo e despeje o drink.","Complete delicadamente com a tônica e decore como preferir.","Coloquei uma laranja desidratada que depois pode ser colocada dentro do drink."]', '', 'Batido', 'Alcoólico', '/uploads/recipes/blue-orange.png'),
('Scuba Tini', '', '[{"name":"Vodka","measure":"180 ml"},{"name":"Licor Curaçau Blue","measure":"30 ml"},{"name":"Suco de Limão","measure":"1 colher bar"}]', '["Coloque a Vodka e o curaçau blue em uma coqueteleira com gelo. Bata na coqueteleira.","Adicione o Suco de Limão.","Coloque a bebida em um copo, use um strainer para coar a bebida sem o gelo."]', '', 'Batido', 'Alcoólico', '/uploads/recipes/SCUBA-TINI.jpg'),
('Blue Tequila Sidecar', '', '[{"name":"Tequila","measure":"45 ml"},{"name":"Suco de Limão","measure":"15 ml"},{"name":"Licor Curaçau Blue","measure":"30 ml"},{"name":"Xarope de Açúcar","measure":"30 ml"}]', '["Em uma coqueteleira adicione os ingredientes com gelo, abale bastante até resfriar a coqueteleira, estirpe em uma taça coupê gelada, coar duplamente, guarnição meia rodela de limão e um twister de limão."]', 'Twister de limão e 1/2 rodela de limão', 'Batido', 'Alcoólico', '/uploads/recipes/Blue-Tequila-Sidecar.png'),
('Monkey Gland', '', '[{"name":"Gin","measure":"60 ml"},{"name":"Suco de Laranja","measure":"30 ml"},{"name":"Grenadine","measure":"15 ml"},{"name":"Absinto","measure":"splash"}]', '["Em uma coqueteleira adicionar os ingredientes com gelo, abale bastante até resfriar a coqueteleira, coar duplamente para uma taça, coloque a guarnição."]', 'Twister de laranja', 'Batido', 'Alcoólico', '/uploads/recipes/Monkey-Gland.png'),
('French 125', '', '[{"name":"Gin","measure":"50 ml"},{"name":"Suco de Limão","measure":"25 ml"},{"name":"Xarope de Açúcar","measure":"10 ml"},{"name":"Espumante","measure":"completar"}]', '["Em uma coqueteleira adicionar os ingredientes com gelo, menos o espumante,  ","Bata até resfriar a coqueteleira, despeje em uma taça de champanhe, coar duplamente","Completar com o espumante, coloque a guarnição."]', 'Casca de laranja', 'Batido', 'Alcoólico', '/uploads/recipes/French-125.png'),
('Lady Blue', '', '[{"name":"Gin","measure":"50 ml"},{"name":"Suco de Limão","measure":"20 ml"},{"name":"Licor Curaçau Blue","measure":"30 ml"},{"name":"Gelo Seco","measure":"1 unidade"}]', '["Em uma coqueteleira, adicione os ingredientes com gelo (seco), abale bastante até resfriar a coqueteleira, estirpe em um copo bem gelado."]', 'Uma cereja', 'Batido', 'Alcoólico', '/uploads/recipes/Lady-Blue.png'),
('Margarita Blue', '', '[{"name":"Tequila","measure":"50 ml"},{"name":"Licor Curaçau Blue","measure":"30 ml"},{"name":"Suco de Limão","measure":"30 ml"}]', '["Em uma coqueteleira, adicione os ingredientes junto com gelo, bata até resfriar a coqueteleira,","Coloque em um copo baixo nem gelado."]', 'Rodela de limão', 'Batido', 'Alcoólico', '/uploads/recipes/MARGARITA-blue.jpg'),
('Caipiroska com Yakult', '', '[{"name":"Vodka","measure":"50 ml"},{"name":"Yakult","measure":"1 unidade"},{"name":"Morangos Maduros","measure":"5 unidades"},{"name":"Açúcar","measure":"2 colheres bar"}]', '["Em uma coqueteleira macere os morangos com o açúcar.","Adicione a Vodka, yakult e gelo e bata por 30 segundos."]', '', 'Batido', 'Alcoólico', '/uploads/recipes/CAIPIROSKA-COM-YAKULT.png'),
('Canarinho', '', '[{"name":"Rum Prata","measure":"30 ml"},{"name":"Suco de Abacaxi","measure":"30 ml"},{"name":"Suco de Laranja","measure":"30 ml"},{"name":"Espumante","measure":"50 ml"},{"name":"Licor Curaçau Blue","measure":"10 ml"}]', '["Em uma coqueteleira, coloque oito cubos de gelo, o Rum Prata, o Suco de Abacaxi e o Suco de Laranja.","Bata tudo em um copo com dois cubos de gelo, despeje o conteúdo coando o gelo da coqueteleira.","Para servir, acrescente o curaçau blue pelo canto do copo."]', 'Ramo de hortelã e uma rodela de laranja', 'Batido', 'Alcoólico', '/uploads/recipes/Canarinho.png'),
('Chinatown', '', '[{"name":"Vodka","measure":"60 ml"},{"name":"Licor de Pêssego","measure":"20 ml"},{"name":"Xarope de Açúcar","measure":"20 ml"},{"name":"Ameixas","measure":""},{"name":"Morangos","measure":""}]', '["Adicione as frutas e hortelã na coqueteleira e macere.","Depois, adicione as bebidas com gelo e bata por 30 segundos.","Sirva em uma taça e decore com as frutas e hortelã."]', 'Ramo de hortelã', 'Batido', 'Alcoólico', '/uploads/recipes/Chinatown.png'),
('Pink Ocean', '', '[{"name":"Gin","measure":"60 ml"},{"name":"Xarope de Pitaya","measure":"15 ml"},{"name":"Xarope de Açúcar","measure":"15 ml"},{"name":"Suco de Limão Siciliano","measure":"25 ml"}]', '["Adicione os ingredientes na coqueteleira com gelo e bata bem!!","Faça dupla coagem para taça.","Finalize com espuma cítrica de limão siciliano."]', 'espuma cítrica de limão siciliano', 'Batido', 'Alcoólico', '/uploads/recipes/PINK-OCEAN.jpg'),
('Caipirinha de Abacaxi', '', '[{"name":"Cachaça","measure":"60 ml"},{"name":"Açúcar","measure":"2 colheres bar"},{"name":"Rodela de Gengibre","measure":"1 unidade"},{"name":"Rodela de Abacaxi","measure":"1 unidade"}]', '["Em uma coqueteleira coloque a rodela de abacaxi, gengibre (picado em pedaços finos) e o açúcar e macere bem.","Coloque a hortelã (sem macerar)","Acrescente a cachaça e gelo e bata bem!"]', 'Ramo de Hortelã', 'Batido', 'Alcoólico', '/uploads/recipes/CAIPIRINHA-DE-ABACAXI.png'),
('Daiquiri de Morango', '', '[{"name":"Rum","measure":"200 ml"},{"name":"Licor de Morango","measure":"50 ml"},{"name":"Morangos","measure":"20 unidades"},{"name":"Suco de Limão","measure":"1 unidade"},{"name":"Açúcar","measure":"3 colheres bar"}]', '["Num liquidificador, adicione 2 copos de gelo picado, 20 morangos, o licor, rum, o limão, o açúcar e bater.","Numa taça de martini, passar na borda limão e depois açúcar.","Servir a bebida."]', 'Twist de limão e um morango com coroa', 'Batido', 'Alcoólico', '/uploads/recipes/Daiquiri-de-Morango.png'),
('Morangolanja', '', '[{"name":"Cachaça","measure":"100 ml"},{"name":"Suco de Laranja","measure":"150 ml"},{"name":"Triple Sec","measure":"50 ml"},{"name":"Morangos","measure":"10 unidades"},{"name":"Açúcar","measure":"3 colheres bar"}]', '["Num liquidificador: acrescentar 10 morangos, 3 colheres (sopa) de açúcar, Suco de Laranja, cachaça e licor.","Num copo médio: adicionar 6 pedras de gelo.","Despejar bebida."]', 'Twist de laranja e um morango', 'Batido', 'Alcoólico', '/uploads/recipes/MORANGOLANJA.jpg'),
('Frozen Margarita', '', '[{"name":"Tequila","measure":"150 ml"},{"name":"Suco de Limão","measure":"200 ml"},{"name":"Triple Sec","measure":"100 ml"}]', '["Em um liquidificador: acrescente 2 copos de gelo picado, a tequila, o Suco de Limão espremido, o licor de laranja e bater.","Em uma taça de martini: passar sal na borda e servir o conteúdo."]', 'Rodela de limão', 'Batido', 'Alcoólico', '/uploads/recipes/FROZEN-MARGARITA.png'),
('Everest', '', '[{"name":"Vodka","measure":"150 ml"},{"name":"Leite de Coco","measure":"50 ml"},{"name":"Leite Condensado","measure":"50 ml"},{"name":"Suco de Abacaxi","measure":"150 ml"},{"name":"Licor Curaçau Blue","measure":"15 ml"}]', '["Num liquidificador: encher de gelo até a metade.","Adicionar a Vodka, o Leite de Coco, o Leite Condensado, o Suco de Abacaxi e bater. ","Passar limão e açúcar na borda.","Colocar o curaçau blue por cima."]', 'Fatia fina de abacaxi e uma cereja', 'Batido', 'Alcoólico', '/uploads/recipes/EVEREST.png'),
('John Collins', '', '[{"name":"Gin","measure":"60 ml"},{"name":"Suco de Limão Siliciano","measure":"30 ml"},{"name":"Xarope de Açúcar","measure":"15 ml"},{"name":"Água com Gás","measure":"completar"}]', '["Encha a coqueteleira de gelo, acrescente o gin, o Suco de Limão e o Xarope de Açúcar","Bata vigorosamente por 10 segundos, depois encha o copo com cubos de gelo.","Sirva o cocktail coado no copo e complete com água gaseificada."]', 'Fatia de limão siciliano e uma cereja ao marasquino', 'Batido', 'Alcoólico', '/uploads/recipes/JOHN-COLLINS.png'),
('Lemon´Rum', '', '[{"name":"Rum","measure":"100 ml"},{"name":"Açúcar","measure":"2 colheres bar"},{"name":"Limão","measure":"1 unidade"}]', '["Misture os pedaços de limão e o açúcar em uma coqueteleira e macere o máximo que puder.","Coloque o gelo e o rum a gosto e agite bem a coqueteleira."]', 'Rodela de limão na borda', 'Batido', 'Alcoólico', '/uploads/recipes/LEMON-RUM.png'),
('Madras', '', '[{"name":"Vodka","measure":"60 ml"},{"name":"Suco de Cranberry","measure":"90 ml"},{"name":"Suco de Laranja","measure":"60 ml"}]', '["Adicione gelo à coqueteleira e coloque todos os ingredientes.","Bata até gelar a coqueteleira e sirva coado no copo com gelo."]', 'Fatia de laranja bahia', 'Batido', 'Alcoólico', '/uploads/recipes/MADRAS.jpg'),
('Killer', '', '[{"name":"Tequila reposado","measure":"60 ml"},{"name":"Suco de Limão","measure":"30 ml"},{"name":"Suco de Abacaxi","measure":"60 ml"},{"name":"Triple Sec","measure":"30 ml"}]', '["Adicione todos ingredientes na coqueteleira com gelo e bata até gelar o cocktail.","Sirva com coagem simples no copo com gelo."]', 'Fatia de abacaxi e cereja ao maraschino', 'Batido', 'Alcoólico', '/uploads/recipes/killer.jpg'),
('Roosevelt', '', '[{"name":"Rum Envelhecido","measure":"60 ml"},{"name":"Suco de Laranja","measure":"7.5 ml"},{"name":"Vermute Extra Seco","measure":"22.5 ml"}]', '["Adicione gelo à taça ou ponha-a no congelador para resfriá-la.","Sirva todos ingredientes na coqueteleira.","Bata até gelar o cocktail e sirva com coagem dupla."]', 'Zest de limão siciliano', 'Batido', 'Alcoólico', '/uploads/recipes/ROOSEVELT.jpg'),
('Dedo de Miga', '', '[{"name":"Tequila","measure":"150 ml"},{"name":"Grenadine","measure":"50 ml"},{"name":"Morangos","measure":"10 unidades"},{"name":"Suco de Limão","measure":"1 unidade"},{"name":"Pimenta Dedo de Moça sem miolo","measure":"1 unidade"}]', '["Num liquidificador: coloque ½ copo de gelo picado, 10 morangos, grenadine, o limão, a pimenta, a tequila e bater.","Em 3 copos de shot:","Passar limão e em seguida açúcar na borda de cada shot fazendo uma borda grossa"]', 'Ponta de morango e fios de casca de limão', 'Batido', 'Shot', '/uploads/recipes/DEDO-DE-MIGA.png'),
('Cachaça Sunrise', '', '[{"name":"Cachaça Ouro","measure":"50 ml"},{"name":"Suco de Laranja","measure":"120 ml"},{"name":"Xarope de Açúcar","measure":"10 ml"},{"name":"Xarope de Groselha","measure":"15 ml"}]', '["Em uma coqueteleira adicione todos os ingredientes menos o xarope de groselha e agite.","Coe para um copo longo cheio de gelo e adicione o xarope de groselha e sirva."]', '', 'Batido', 'Alcoólico', '/uploads/recipes/Cachaca-Sunrise.png'),
('Adrenalina', '', '[{"name":"Vodka","measure":"300 ml"},{"name":"Licor de Menta","measure":"150 ml"},{"name":"Leite Condensado","measure":"200 g"}]', '["Bata no liquidificador a Vodka, o licor de menta e o Leite Condensado por 10 segundos","Acrescente o gelo e bata por mais 10 segundos, sirva."]', 'Guarda chuvinha', 'Batido', 'Alcoólico', '/uploads/recipes/Adrenalina.png'),
('Russian Kiss', '', '[{"name":"Vodka","measure":"30 ml"},{"name":"Club Soda","measure":"150 ml"},{"name":"Grenadine","measure":"50 ml"},{"name":"Cerejas","measure":"3 unidades"}]', '["Amasse bem as cerejas na coqueteleira junto com o grenadine.","Depois misture a Vodka, o club soda, o gelo e bata bem.","Sirva coando o gelo."]', '', 'Batido', 'Alcoólico', '/uploads/recipes/russian-kiss.png'),
('Caipirinha de Cerveja', '', '[{"name":"Cachaça","measure":"150 ml"},{"name":"Cerveja","measure":"600 ml"},{"name":"Açúcar","measure":"3 colheres bar"},{"name":"Limões","measure":"2 unidades"}]', '["Com elas geladinhas, corte os limões em quatro. Em uma coqueteleira, coloque os limões e o açúcar e amasse bem. Coloque as doses de cachaça, o gelo e mexa bem. Sirva a caipirinha até metade do copo e complete com a cerveja.","Antes de colocar a caipirinha, molhe a borda do copo e passe no açúcar. Você também pode colocar uma rodela de limão para enfeitar!","Essa receita rende até 4 copos de caipirinha de cerveja."]', '', 'Batido', 'Alcoólico', '/uploads/recipes/CAIPIRINHA-DE-CERVEJA.png'),
('Raspadinha de Abacaxi', '', '[{"name":"Leite Condensado","measure":"1 lata"},{"name":"Abacaxi","measure":"2 latas"}]', '["Coloque o Leite Condensado no copo do liquidificador e junte o abacaxi.","Bata bem até que se transforme em um creme.","Junte 6 copos altos com o gelo e bata o gelo com o creme."]', '', 'Batido', 'Sem Álcool', '/uploads/recipes/RASPADINHA-DE-ABACAXI.jpg'),
('Jurubreja', '', '[{"name":"Jurupinga","measure":"250 ml"},{"name":"Suco de Limão","measure":"2 unidades"},{"name":"Cerveja","measure":"completar"}]', '["Em um copo: passe limão na borda, passe sal na borda","Em um liquidificador, bater: o gelo triturado, 1 copo de jurupinga e os 2 limões espremidos","Em um copo médio: despejar bebida e enfiar uma garrafa de cerveja gelada"]', 'Rodela de limão borda', 'Batido', 'Alcoólico', '/uploads/recipes/Jurubreja.png'),
('Batidinha de Jurupinga', '', '[{"name":"Jurupinga","measure":"100 ml"},{"name":"Polpa de Maracujá","measure":"1 unidade"},{"name":"Leite Condensado","measure":"1/2 lata"},{"name":"Açúcar","measure":"2 colheres bar"}]', '["Bater todos os ingredientes no liquidificador","Colocar o gelo em taças grandes","Despejar a bebida"]', '2 colheres de polpa de maracujá', 'Batido', 'Alcoólico', '/uploads/recipes/Batidinha-de-Jurupinga.png'),
('Blue Hawaiian', '', '[{"name":"Rum Prata","measure":"40 ml"},{"name":"Malibu","measure":"10 ml"},{"name":"Licor Curaçau Blue","measure":"10 ml"},{"name":"Suco de Abacaxi","measure":"100 ml"}]', '["Junte todos os ingredientes na coqueteleira e mexa bem.","Sirva em um copo longo cheio de gelo e decore com pedaços de abacaxi."]', 'Pedaço de abacaxi', 'Batido', 'Alcoólico', '/uploads/recipes/Blue-Hawaiian.png'),
('Morana ´Slut', '', '[{"name":"Vodka","measure":"100 ml"},{"name":"Leite Condensado","measure":"1/2 lata"},{"name":"Creme de Leite","measure":"1/2 caixinha"},{"name":"Morangos","measure":"5 unidades"},{"name":"Banana","measure":"1 unidade"}]', '["Coloque todos os ingredientes no liquidificador e bata bem.","Se achar que ficou muito forte, pode dar uma quebrada com açúcar;","Se achar que ficou fraco, pode acrescentar mais Vodka"]', '', 'Batido', 'Alcoólico', '/uploads/recipes/Morana-Slut.jpg'),
('Black Flairy', '', '[{"name":"Absinto","measure":"15 ml"},{"name":"Whisky","measure":"15 ml"},{"name":"Suco de Limão","measure":"15 ml"},{"name":"Água Tônica ou Soda Limonada","measure":"15 ml"},{"name":"Amoras","measure":"4 unidades"}]', '["Coloque na coqueteleira 3 amoras, com umas folhas de hortelã e macere.","Adicione o absinto, o whisky, o Suco de Limão e a água tônica.","Adicione umas pedras de gelo e bata bem.","Coe e sirva em um copo de short drink, aquele médio, com gelo."]', '1 amora e umas folhas de hortelã', 'Batido', 'Alcoólico', '/uploads/recipes/Black-Flairy.png'),
('Frozen Sex', '', '[{"name":"Vodka","measure":"125 ml"},{"name":"Licor de Café","measure":"1 fio"},{"name":"Sorvete de Chocolate","measure":"6 colheres de sopa"}]', '["Coloque 6 colheres de sorvete no liquidificador com os alcoólicos e bata em baixa velocidade.","Quando estiver na consistência que vc achar legal, inclua o gelo, mas não deixe bater muito e sirva."]', 'Chantilly', 'Batido', 'Alcoólico', '/uploads/recipes/Frozen-Sex.png'),
('Virgin Pinã Colada', '', '[{"name":"Leite de Coco","measure":"100 ml"},{"name":"Suco de Abacaxi","measure":"350 ml"},{"name":"Açúcar","measure":"1 colher bar"}]', '["Bata o Leite de Coco, o açúcar e o suco na coqueteleira.","Encha um copo de long drink de gelo quebrado."]', 'Pedaço de abacaxi e coco ralado', 'Batido', 'Sem Álcool', '/uploads/recipes/Virgin-Pina-Colada.jpg'),
('Lemanjá', '', '[{"name":"Cachaça","measure":"50 ml"},{"name":"Suco de Abacaxi","measure":"50 ml"},{"name":"Água de Coco","measure":"50 ml"},{"name":"Açúcar","measure":"1 colher bar"}]', '["Bata bem os ingredientes numa coqueteleira com cubos de gelo.","Sirva em um copo alto e pronto."]', 'Meia fatia de abacaxi com casca', 'Batido', 'Alcoólico', '/uploads/recipes/Lemanja.jpg'),
('Espanhola', '', '[{"name":"Vinho Tinto Suave","measure":"1 litro"},{"name":"Leite Condensado","measure":"1 lata"},{"name":"Abacaxi médio sem o miolo","measure":"1 unidade"}]', '["Comece descascando e cortando o abacaxi, leve ao liquidificador juntamente com o Leite Condensado e com o vinho.","Acrescente então o gelo e bata novamente","Sirva em copos largos."]', '', 'Batido', 'Alcoólico', '/uploads/recipes/Espanhola.png'),
('Sugar Citrus', '', '[{"name":"Vodka","measure":"100 ml"},{"name":"Soda Limonada","measure":"200 ml"},{"name":"Suco de Abacaxi com Hortelã","measure":"suco de saquinho"},{"name":"Leite Condensado","measure":"a gosto"}]', '["Coloque na coqueteleira a Vodka e o refrigerante e misture os dois ingredientes;","Em outro recipiente, coloque o suco de saquinho junto com uma porção a gosto de Leite Condensado;","Misture bem o Leite Condensado com o pó do suco, até ficar bem homogênea a mistura e coloque a mistura junto na coqueteleira, mexa e pronto."]', '', 'Batido', 'Alcoólico', '/uploads/recipes/sugar-citrus.png'),
('Caipiroska de Yakult', '', '[{"name":"Vodka","measure":"50 ml"},{"name":"Limão","measure":"1 unidade"},{"name":"Açúcar","measure":"2 colheres bar"},{"name":"Yakult","measure":"1 unidade"}]', '["Em uma coqueteleira coloque o limão em pedaços.","Macere levemente (para extrair o suco).","Adicione a Vodka e o yakult e coloque gelo e bata bem."]', 'Twist de limão', 'Batido', 'Alcoólico', '/uploads/recipes/CAIPIROSKA-DE-YAKULT.png'),
