('Caipirinha Morango com Picolé de Limão', '', '[{"name":"Cachaça","measure":"50 ml"},{"name":"Morangos","measure":"4 unidades"},{"name":"Açúcar","measure":"1 colher bar"},{"name":"Picolé de Limão","measure":"1 unidade"}]', '["Macere os morangos com o açúcar numa coqueteleira.","Coloque a cachaça e o gelo e misture bastante.","Sirva colocando um picolé de limão."]', '', 'Batido', 'Alcoólico', '/uploads/recipes/Caipirinha-de-morango-com-picole-de-limao.png'),
('Blue Margarita', '', '[{"name":"Tequila","measure":"200 ml"},{"name":"Cointreau","measure":"50 ml"},{"name":"Licor Curaçau Blue","measure":"100 ml"},{"name":"Suco de Limão","measure":"50 ml"},{"name":"Açúcar","measure":"1 colher bar"}]', '["Colocar gelo até a metade da coqueteleira, adicione todos os ingredientes e bata por uns 30 segundos.","Fazer a borda do copo com limão e o sal;","Sirva no copo com gelo."]', 'Fatia de limão', 'Batido', 'Alcoólico', '/uploads/recipes/Blue-Margarita.png'),
