('Green Drink', '', '[{"name":"Vodka","measure":"80 ml"},{"name":"Licor de Creme de Menta","measure":"50 ml"},{"name":"Suco de Limão","measure":"1 unidade"},{"name":"Açúcar","measure":"2 colher bar"},{"name":"Água com Gás","measure":"completar"}]', '["Num copo de 480ml coloque o Suco do Limão, as duas colheres de Açúcar e o Licor de Creme de Menta e misture bem;","Depois complete o copo com gelo triturado; agora coloque a Vodka e completa com Água com Gás e finalize com o anis estrelado."]', 'Anis estrelado', 'Montado', 'Alcoólico', '/uploads/recipes/GREEN_DRINK.jpg'),
('Strawberry Cold', '', '[{"name":"Vodka","measure":"30 ml"},{"name":"Rum","measure":"20 ml"},{"name":"Suco de Limão","measure":"½ unidade"},{"name":"Morango","measure":"6 unidades"}]', '["Macere os Morangos junto com o Suco de Limão adicione o gelo, a Vodka e o Rum, misture e sirva e por fim decore com Morango."]', 'Morango', 'Montado', 'Alcoólico', '/uploads/recipes/STRAWBERRY_COLD.jpg'),
('Deep Blue', '', '[{"name":"Gin","measure":"50 ml"},{"name":"Licor de Curaçau Blue","measure":"10 ml"},{"name":"Água Tônica ou Água com Gás","measure":"completar"}]', '["Gele a taça. Retire a Água que fica ao fundo. Adicione o Gin e Curaçau Blue.","Aromatize com zimbro e twist de Limão Siciliano.","E por último adicione a Água Tônica com cuidado para não perder o gás.","Uma dica é para aqueles que não curtem o sabor amargo, acrescente uma colher de sopa de Xarope de Açúcar ou Xarope de Limão Siciliano!"]', 'Twist de Limão Siciliano e Zimbro', 'Montado', 'Alcoólico', '/uploads/recipes/DEEP_BLUE.png'),
('Blue Crystal', '', '[{"name":"Licor de Curaçau Blue","measure":"40 ml"},{"name":"Soda Limonada","measure":"completar"},{"name":"Suco de Laranja","measure":"1 fatia"},{"name":"Gelo azul feito com corante comestível","measure":""}]', '["Coloque gelo no copo, em seguida o Curaçau e o refrigerante. Misture com uma colher bailarina. E para finalizar com cuidado as fatias de Laranja e uma Hortelã para enfeitar."]', 'Fatia de laranja e Hortelã', 'Montado', 'Alcoólico', '/uploads/recipes/BLUE_CRYSTAL.jpg'),
('Whiskey With Soda', '', '[{"name":"Whiskey","measure":"60 ml"},{"name":"Soda Limonada","measure":"completar"}]', '["Macere as folhas Hortelã no fundo do copo, adicione Whiskey, gelo e limões nas laterais do copo, complete com a soda."]', '', 'Montado', 'Alcoólico', '/uploads/recipes/WHISKY_WITH_SODA.jpg'),
('Caipilaço', '', '[{"name":"Cachaça Prata","measure":"100 ml"},{"name":"Melaço de Cana","measure":"50 ml"},{"name":"Suco de Limão","measure":"1 unidade"}]', '["Passe o Limão na borda e depois num pires, o sal. Adicione a Cachaça, o melado e o Limão, misture, e decore com uma rodela de Limão."]', 'Sal e Limão para borda', 'Montado', 'Alcoólico', '/uploads/recipes/Caipilaco.jpg'),
