('Gin Tropical', '', '[{"name":"Gin","measure":"50 ml"},{"name":"Energético Tropical","measure":"completar"}]', '["Em uma taça, adicione o Gin, complete a taça com gelo, coloque a rodela de Laranja na lateral do copo e complete com o energético."]', '1 rodela de Laranja Bahia', 'Montado', 'Alcoólico', '/uploads/recipes/GIN_TROPICAL.jpg'),
('Maracugin', '', '[{"name":"Gin","measure":"50 ml"},{"name":"Açúcar","measure":"2 colheres de bar"},{"name":"Polpa de Maracujá","measure":"3 colheres de bar"},{"name":"Água Tônica","measure":"completar"}]', '["Em uma taça acrescente o gelo, logo em seguida o Gin.","Adicione o Maracujá juntamente com Açúcar.","Complete com Água Tônica dando uma leve mexida.","Acrescente um ramo de alecrim."]', 'Ramo de alecrim', 'Montado', 'Alcoólico', '/uploads/recipes/MARACUGIN.jpg'),
('Espresso Gin Tônica', '', '[{"name":"Gin","measure":"50 ml"},{"name":"Suco de Limão","measure":"½ unidade"},{"name":"Café Espresso","measure":"5 ml"},{"name":"Água Tônica","measure":"completar"}]', '["Em uma taça adicione o café o Suco do Limão, o Gin, mexa suavemente, adicione o gelo e a Água Tônica, de uma leve mexida, guarnição rodela de Limão."]', 'Rodela de limão', 'Montado', 'Alcoólico', '/uploads/recipes/ESPRESSO_GIN_TONICA.jpg'),
('Caipirinha com Chá Vermelho', '', '[{"name":"Cachaça","measure":"60 ml"},{"name":"Chá Vermelho","measure":"15 ml"},{"name":"Limão","measure":"1 unidade"},{"name":"Açúcar","measure":"2 colheres de bar"}]', '["Prepara o Limão no copo, coloca o Açúcar, macere bem e coloque o gelo","Sobre o gelo, coloca a Cachaça e mexa bem","Agora, coloca o Chá vermelho e só mexe quando for beber.","Assim, você servirá com um visual lindo, bifásico."]', '', 'Montado', 'Alcoólico', '/uploads/recipes/CAIPIRINHA_CHA_VERMELHO.jpg'),
('Power Drill', '', '[{"name":"Vodka","measure":"60 ml"},{"name":"Suco de Laranja","measure":"60 ml"},{"name":"Cerveja","measure":"completar"}]', '["Em um copo com gelo ao topo coloque a Vodka, o Suco de Laranja, mexa para misturar, complete com a cerveja, guarnição rodela de Laranja."]', 'Rodela de Laranja', 'Montado', 'Alcoólico', '/uploads/recipes/POWER_DRILL.jpg'),
('Sweet Sunrise', '', '[{"name":"Suco de Laranja","measure":"120 ml"},{"name":"Xarope de Grenadine","measure":"15 ml"}]', '["Em um compro longo com bastante gelo, despeje o Suco de Laranja, mexa para gelar o suco, depois aos poucos despeje o Xarope de Grenadine, está pronto seu cocktail sem álcool."]', 'Fatia de Laranja', 'Montado', 'Sem Álcool', '/uploads/recipes/SWEET_SUNRISE.jpg'),
('Deep Blue Sea', '', '[{"name":"Vodka","measure":"45 ml"},{"name":"Licor de Curaçau Blue","measure":"15 ml"},{"name":"Energético RB Edition Blueberry","measure":"completar"}]', '["Em um copo com gelo até o topo, adicione a Vodka e o Curaçau Blue, mexa para gelar, complete com o Energético ."]', '', 'Montado', 'Alcoólico', '/uploads/recipes/Deep_blue_sea.png'),
('Gin Tônica com Licor de Morango', '', '[{"name":"Gin","measure":"50 ml"},{"name":"Licor de Morango","measure":"15 ml"},{"name":"Água Tônica","measure":"completar"}]', '["Adicione o Licor de Morango e o Gin em uma taça, preencha ela inteira com gelo e complete com Água Tônica. Mexa (debaixo para cima, para homogeneizar os ingredientes), para decorar, especiarias como alecrim ou Hortelã."]', 'Morango e Ramo Hortelã', 'Montado', 'Alcoólico', '/uploads/recipes/GIN_TONICA_COM_LICOR_DE_MORANGO.jpg'),
('Gin Monster', '', '[{"name":"Gin","measure":"50 ml"},{"name":"Energético Monster Khaos","measure":"completar"}]', '["Em uma taça de Gin coloque gelo.","Mexa com a bailarina até gelar a taça, tire a Água com uma peneira.","Coloque a guarnição (grapefruit ou Laranja).","Complete com o monster e misture levemente."]', 'Rodela Laranja Bahia', 'Montado', 'Alcoólico', '/uploads/recipes/GIN_MONSTER.png'),
('Gin Tônica Red', '', '[{"name":"Gin","measure":"50 ml"},{"name":"Groselha ou Xarope de Grenadine","measure":"20 ml"},{"name":"Água Tônica","measure":"completar"}]', '["Adicione o Gin e a Groselha numa taça com gelo e mexa levemente e complete com a Água Tônica."]', '', 'Montado', 'Alcoólico', '/uploads/recipes/gin_tonica_red.jpg'),
('O Monstro Azul', '', '[{"name":"Vodka","measure":"30 ml"},{"name":"Rum","measure":"30 ml"},{"name":"Suco de Limão","measure":"30 ml"},{"name":"Soda Limonada","measure":"30 ml"},{"name":"Licor de Curaçau Blue","measure":"Splash"}]', '["Encha um copo com gelo e despeje Vodka, Rum e um pouco de Curaçau azul.","Adicione o Suco de Limão e cubra com refrigerante de Limão.","Decore com uma fatia de Limão."]', 'Fatia de limão', 'Montado', 'Alcoólico', '/uploads/recipes/O_MONSTRO_AZUL.jpg'),
('Caipirinha de Cerveja Rústica', '', '[{"name":"Cachaça Ouro","measure":"100 ml"},{"name":"Suco de Limões","measure":"2 unidades"},{"name":"Limão em fatias","measure":"½ unidade"},{"name":"Açúcar","measure":"1 colher de bar"},{"name":"Cerveja Preta","measure":"completar"}]', '["Em um copo grande: passar Limão na borda e em um prato, colocar sal e passar na borda.","Colocar gelo até a metade do copo, ½ Limão em fatias, 2 limões espremidos, o Açúcar e a Cachaça. Mexer até dissolver o Açúcar.","Completar com cerveja preta.","Decorar com uma rodela de Limão."]', 'Rodela de limão', 'Montado', 'Alcoólico', '/uploads/recipes/CAIPIRINHA_DE_CERVEJA_RUSTICA.png'),
('Maze', '', '[{"name":"Gin","measure":"50 ml"},{"name":"Skol Beats 150BPM","measure":"1 unidade"},{"name":"Suco de Limão","measure":"1 unidade"},{"name":"Schweppes Citrus","measure":"completar"}]', '["Em uma taça com gelo coloque Gin, Limão e beats 150.","Complete com Schweppes."]', '', 'Montado', 'Alcoólico', '/uploads/recipes/MAZE.jpg'),
('Cranberry Julep', '', '[{"name":"Whiskey","measure":"50 ml"},{"name":"Hortelã","measure":"10 folhas"},{"name":"Açúcar","measure":"1 colher de bar"},{"name":"Suco de Cranberry","measure":"completar"}]', '["Em um copo alto: colocar as 10 folhas Hortelã amassadas e 1 colher de bar Açúcar.","Encher de gelo, acrescentar o Whiskey e completar com Suco de Cranberry."]', '3 folhas Hortelã', 'Montado', 'Alcoólico', '/uploads/recipes/CRANBERRY_JULEP.png'),
('Chapolin', '', '[{"name":"Tequila","measure":"100 ml"},{"name":"Licor de Morango","measure":"25 ml"},{"name":"Morangos","measure":"5 unidades"},{"name":"Suco de Laranja","measure":"completar"}]', '["Num copo weiss: colocar os 5 Morangos, o Licor e macerar.","Intercalar gelo, Morangos cortados em forma de coração.","Acrescentar a Tequila e completar com Suco de Laranja.","Decorar usando 2 canudos, um em cada lado com 1 Morango preso em cada ponta, como antena."]', '', 'Montado', 'Alcoólico', '/uploads/recipes/CHAPOLIN.png'),
('Cranberry Cubano', '', '[{"name":"Rum","measure":"50 ml"},{"name":"Hortelã","measure":"5 folhas"},{"name":"Açúcar","measure":"1 colher de bar"},{"name":"Suco de Limão","measure":"½ unidade"},{"name":"Suco de Cranberry","measure":"completar"}]', '["Em um copo alto: colocar as 5 folhas Hortelã, o Açúcar e macerar.","Completar copo com gelo triturado.","Acrescentar Limão espremido, Rum e completar com Suco de Cranberry.","Decorar com um ramo Hortelã e colocar um canudo."]', '', 'Montado', 'Alcoólico', '/uploads/recipes/CRAnBERRY_CUBANO.jpg'),
