('Caipiroska Amarelinha', '', '[{"name":"Vodka","measure":"50 ml"},{"name":"Suco de Abacaxi","measure":"50 ml"},{"name":"Limão Siciliano","measure":"1 unidade"},{"name":"Açúcar","measure":"1 colher de bar"}]', '["Em um copo baixo: acrescentar o Limão Siciliano picado, o Açúcar e macerar.","Encher de gelo em cubo até em cima.","Misturar e enfiar garrafinha de absolut.","Decorar usando uma rodela de Limão Siciliano, pedaços de Limão em cima do gelo e colocar um canudo."]', '', 'Montado', 'Alcoólico', '/uploads/recipes/CAIPIROSKA_AMARELINHA.png'),
('Magali', '', '[{"name":"Rum Prata","measure":"100 ml"},{"name":"Melancia","measure":"1 pedaço"},{"name":"Suco de Limão Siciliano","measure":"½ unidade"},{"name":"Açúcar","measure":"2 colheres de bar"}]', '["Num copo, colocar um pedaço de melancia cortado em 4, ½ unidade Suco Limão Siciliano, 2 colheres de bar Açúcar e macerar.","Intercalar rodela de Limão Siciliano e gelo até em cima, acrescentar o Rum Prata e misturar.","Decorar usando um ramo Hortelã, uma rodela de Limão Siciliano na borda e colocar um canudo."]', 'Limão Siciliano em rodela e ramo Hortelã', 'Montado', 'Alcoólico', '/uploads/recipes/magali.jpg'),
('Elevated Screwdriver', '', '[{"name":"Vodka","measure":"50 ml"},{"name":"Suco de Laranja","measure":"150 ml"},{"name":"Vinho Frisante ou Prosecco, Espumante","measure":"completar"}]', '["Em um copo longo: encher de gelo, acrescentar a Vodka e o Suco de Laranja.","Completar com Vinho Frisante ou prosecco, Espumante.","Decorar com fatias finas de Laranja."]', 'Laranja em fatias', 'Montado', 'Alcoólico', '/uploads/recipes/ELEVATED_SCREWDRIVER.jpg'),
('Gin Toddy', '', '[{"name":"Gin","measure":"100 ml"},{"name":"Água sem Gás","measure":"30 ml"},{"name":"Limão","measure":"5 gotas"},{"name":"Limão","measure":"1 fatia"}]', '["Misture o Gin com a água, some as 5 gotas e a fatia de Limão."]', '', 'Montado', 'Alcoólico', '/uploads/recipes/GIN_TODDY.jpg'),
('Drink Thug Life', '', '[{"name":"Tequila","measure":"50 ml"},{"name":"Abacaxi","measure":"1 rodela"},{"name":"Açúcar","measure":"1 colher de bar"},{"name":"Suco de Laranja","measure":"2 Unidades"}]', '["Num copo alto: acrescentar a rodela do Abacaxi picada, 1 colher de bar Açúcar e macerar.","Colocar as 2 Laranjas espremidas e encher de gelo triturado.","Incluir a Tequila e mexer.","Decorar com a casca do Abacaxi."]', '', 'Montado', 'Alcoólico', '/uploads/recipes/DRINK_THUG_LIFE.jpg'),
('Gengijack', '', '[{"name":"Whiskey Jack Daniels","measure":"50 ml"},{"name":"Açúcar","measure":"1 colher de bar"},{"name":"Gengibre","measure":"1 colher de bar ralado"},{"name":"Suco de Limão","measure":"1 unidade"},{"name":"Abacaxi Congelado","measure":"2 pedaços"},{"name":"Água com Gás","measure":"completar"}]', '["Em um copo baixo: coloque 1 colher de gengibre ralado na peneira, o Limão espremido na peneira e pressione o gengibre.","Acrescentar o Whiskey, 1 colher de bar Açúcar e mexer.","Adicione 3 pedras de gelo, 2 pedaços de Abacaxi congelado e completar com Água com Gás, decorar usando uma rodela de Limão na borda."]', 'Rodela de limão', 'Montado', 'Alcoólico', '/uploads/recipes/GENGIJACK.png'),
