('Gold Velvet', '', '[{"name":"Cerveja Pilsen","measure":"½ copo"},{"name":"Suco de Abacaxi","measure":"50 ml"},{"name":"Prosecco, Espumante","measure":"completar"}]', '["Numa taça, misture a cerveja com o Suco de Abacaxi e complete com o espumante."]', '', 'Montado', 'Alcoólico', '/uploads/recipes/GOLD_VELVET.jpg'),
('Honey Tea', '', '[{"name":"Whiskey","measure":"50 ml"},{"name":"Licor de Laranja","measure":"25 ml"},{"name":"Mel","measure":"3 colheres de bar"},{"name":"Hortelã","measure":"8 folhas"},{"name":"Chá Mate","measure":"1 unidade"}]', '["Em um copo grande: adicionar as colheres de mel, Licor de Laranja, Whiskey e mexer até dissolver o mel.","Encher de gelo e acrescentar as folhas Hortelã.","Completar com Chá mate sem Açúcar e mexer."]', 'Ramo de Hortelã', 'Montado', 'Alcoólico', '/uploads/recipes/HONEY_TEA.jpg'),
('Ilha Verde', '', '[{"name":"Vodka","measure":"150 ml"},{"name":"Suco de Abacaxi","measure":"150 ml"},{"name":"Licor de Creme de Menta","measure":"25 ml"},{"name":"Açúcar","measure":"2 colheres de bar"},{"name":"Suco de Limão Siciliano","measure":"1 unidade"}]', '["Num copo grande: coloque o gelo até metade do copo, as colheres de Açúcar, a Vodka, o Limão espremido, o Suco de Abacaxi, o Licor de Creme de Menta e misturar.","Decorar usando 2 pedaços de casca do Limão Siciliano retorcida e colocar um canudo."]', '2 twists de Limão Siciliano', 'Montado', 'Alcoólico', '/uploads/recipes/ILHA_VERDE.jpg'),
('Juruná', '', '[{"name":"Jurupinga","measure":"½ copo"},{"name":"Suco de Laranja","measure":"1 unidade"},{"name":"Guaraná Antárctica","measure":"completar"}]', '["Em um copo médio: acrescente o gelo, a Jurupinga e a Laranja espremida.","Intercalar gelo triturado com meia rodela de Laranja e completar com guaraná antártica.","Decorar usando rodela de Laranja na borda, um ramo Hortelã e colocar um canudo."]', 'Rodela de Laranja na borda, um ramo Hortelã', 'Montado', 'Alcoólico', '/uploads/recipes/JURUNA.png'),
('Jurulé', '', '[{"name":"Polpa de Maracujá","measure":"½ unidade"},{"name":"Açúcar","measure":"1 colher de bar"},{"name":"Suco de Limão","measure":"15 ml"},{"name":"Picolé de Uva","measure":"1 unidade"},{"name":"Jurupinga","measure":"completar"}]', '["Num copo de caipirinha: adicione o Maracujá, Açúcar, Limão espremido e completar com Jurupinga bem gelada.","Mexer e acrescentar um Picolé de Uva.","Completar o copo com gelo triturado."]', 'Fatia de limão', 'Montado', 'Alcoólico', '/uploads/recipes/JURULe.png'),
('Jurupinga Submarina', '', '[{"name":"Xarope de Grenadine","measure":"25 ml"},{"name":"Tequila","measure":"25 ml"},{"name":"Jurupinga","measure":"completar"}]', '["Num copo de dose: colocar a Groselha, a Tequila e misturar.","Colocar de ponta cabeça em uma caneca grande.","Completar com Jurupinga bem gelada."]', '1 morango', 'Montado', 'Alcoólico', '/uploads/recipes/JURUPINGA_SUBMARINA.jpg'),
('Lagoa Azul', '', '[{"name":"Vodka","measure":"25 ml"},{"name":"Licor de Curaçau Blue","measure":"50 ml"},{"name":"Suco de Limão","measure":"½ unidade"},{"name":"Soda Limonada","measure":"completar"}]', '["Em um copo longo de cocktail: colocar o gelo até encher, a Vodka, o Limão espremido, as fatias de Limão, o Curaçau Blue e completar com a soda.","Decorar com uma fatia de Limão e uma Cereja."]', 'Fatia de limão e uma cereja', 'Montado', 'Alcoólico', '/uploads/recipes/Lagoa_Azul_II.jpg'),
('Maracugin versão 2', '', '[{"name":"Gin","measure":"100 ml"},{"name":"Polpa de Maracujá","measure":"50 ml"},{"name":"Hortelã","measure":"12 folhas"},{"name":"Açúcar","measure":"2 colheres de bar"},{"name":"Suco de Limão Siciliano","measure":"1 unidade"},{"name":"Gengibre","measure":"4 rodelas"}]', '["Num copo alto: adicionar a Hortelã, o Açúcar, o Limão e macerar.","Acrescentar as rodelas de gengibre e macerar novamente.","Gelo até a metade, colocar a Polpa de Maracujá, o Gin e completar com Água Tônica. Mexer levemente e completar com gelo.","Decorar com um pedaço da casca do Maracujá e um ramo Hortelã."]', 'Casca do Maracujá e um ramo Hortelã', 'Montado', 'Alcoólico', '/uploads/recipes/MARACUGIN_II.jpg'),
('Mojito de Abacaxi', '', '[{"name":"Rum Branco","measure":"100 ml"},{"name":"Hortelã","measure":"10 folhas"},{"name":"Açúcar","measure":"2 colheres de bar"},{"name":"Abacaxi","measure":"1 rodela"},{"name":"Limão","measure":"1 unidade"},{"name":"Água com Gás","measure":"completar"}]', '["Num copo alto: adicionar as folhas Hortelã, Açúcar, o Abacaxi piscado, o Limão cortado e macerar.","Depois acrescente as pedras de gelo, o Rum e misturar.","Completar com Água com Gás e dar uma leve mexida.","Colocar um canudo."]', '3 folhas da coroa do Abacaxi, um ramo Hortelã', 'Montado', 'Alcoólico', '/uploads/recipes/MOJITO_DE_ABACAXI.jpg'),
('Morango Blue', '', '[{"name":"Vodka","measure":"50 ml"},{"name":"Rum","measure":"50 ml"},{"name":"Cointreau (Triple Sec)","measure":"50 ml"},{"name":"Licor de Curaçau Blue","measure":"50 ml"},{"name":"Suco de Abacaxi","measure":"50 ml"},{"name":"Morangos","measure":"5 unidades"}]', '["Em uma taça de Vinho: encher de gelo e Morango intercalados.","Acrescentar todos os ingredientes.","Decorar com um Morango."]', 'Um morango', 'Montado', 'Alcoólico', '/uploads/recipes/MORANGO_BLUE.jpg'),
('Mojito Mágico de Abacaxi', '', '[{"name":"Rum","measure":"50 ml"},{"name":"Hortelã","measure":"10 folhas"},{"name":"Suco de Limão","measure":"½ unidade"},{"name":"Açúcar","measure":"2 colheres de bar"},{"name":"Abacaxi","measure":"2 rodelas"},{"name":"Prosecco, Espumante ou Vinho Frisante","measure":"completar"}]', '["Em um copo alto: acrescente as folhas Hortelã, o Limão, o Açúcar e macerar levemente.","Encher de Abacaxi picado até a metade do copo e macerar novamente.","Completar com gelo, adicionar o Rum e completar com Prosecco, Espumante ou Vinho Frisante.","Decorar com um pedaço de Abacaxi e Hortelã."]', 'Pedaço de Abacaxi e Hortelã', 'Montado', 'Alcoólico', '/uploads/recipes/MOJITO_MAGICO_DE_ABACAXI.jpg'),
('New York Sour', '', '[{"name":"Whiskey","measure":"100 ml"},{"name":"Vinho Tinto Seco","measure":"25 ml"},{"name":"Suco de Limão Siciliano","measure":"½ unidade"},{"name":"Açúcar","measure":"1 colher de bar"}]', '["Em um copo baixo: acrescentar as pedras de gelo, Limão espremido, Whiskey, Açúcar e mexer.","Adicionar a fatia em meia lua de Limão Siciliano e o Vinho Tinto Seco."]', '½ Fatia de Limão Siciliano', 'Montado', 'Alcoólico', '/uploads/recipes/NEW_YORK_SOUR.jpg'),
('One Source', '', '[{"name":"Vodka","measure":"100 ml"},{"name":"Suco de Maçã","measure":"100 ml"},{"name":"Suco de Limão Siciliano","measure":"25 ml"},{"name":"Água sem Gás Fervenda","measure":"25 ml"},{"name":"Mel","measure":"1 colher de bar"},{"name":"Água com Gás","measure":"completar"}]', '["Em um copo alto: adicionar todos os ingredientes menos o gelo e Água com Gás, e mexer.","Encher de gelo e completar com Água com Gás.","Decorar com umas fatias finas de Limão Siciliano."]', 'Fatias finas de Limão Siciliano', 'Montado', 'Alcoólico', '/uploads/recipes/ONE_SOURCE.jpg'),
('Paloma', '', '[{"name":"Tequila Blanco ou Prata","measure":"60 ml"},{"name":"Suco de Toranja (Grapefruit)","measure":"30 ml"},{"name":"Suco de Limão","measure":"15 ml"},{"name":"Schweppes Citrus","measure":"completar"}]', '["Adicione gelo ao copo.","Sirva a Tequila e os dois sucos.","Adicione o refrigerante citrus a uma certa altura do copo que ela se misture naturalmente com os demais ingredientes","Decorar com gomo de grapefruit."]', 'Um gomo de grapefruit', 'Montado', 'Alcoólico', '/uploads/recipes/PALOMA.jpg'),
('Passion Mojito', '', '[{"name":"Rum Branco","measure":"50 ml"},{"name":"Hortelã","measure":"10 folhas"},{"name":"Açúcar","measure":"2 colheres de bar"},{"name":"Polpa de Maracujá","measure":"2 colher de bar"},{"name":"Vinho Frisante ou Prosecco, Espumante","measure":"completar"}]', '["Em um copo alto: adicionar as folhas Hortelã, o Açúcar, o Rum e macerar.","Gelo até a metade e acrescentar o Maracujá e as fatias de Limão Siciliano.","Complete com Vinho Frisante ou prosecco, Espumante."]', 'Fatias de Limão Siciliano', 'Montado', 'Alcoólico', '/uploads/recipes/PASSION_MOJITO.jpg'),
('Pink Beer', '', '[{"name":"Suco de Cranberry","measure":"50 ml"},{"name":"Suco de Limão Siciliano","measure":"1 unidade"},{"name":"Cerveja","measure":"completar"}]', '["Em uma caneca de chopp: colocar as pedras de gelo, o Limão, o Suco e completar com a cerveja.","Jogar pimenta rosa moída por cima.","Decorar com uma 1 fatia de Limão Siciliano + 1 pedaço da casca cortada em espiral."]', 'fatia de Limão Siciliano e Pedaço da casca cortada em espiral', 'Montado', 'Alcoólico', '/uploads/recipes/PINK_BEER.png'),
('Red Mix Maracujá', '', '[{"name":"Whiskey","measure":"50 ml"},{"name":"Polpa de Maracujá","measure":"½ unidade"},{"name":"Açúcar","measure":"2 colheres de bar"}]', '["Coloque num copo de long drink a Polpa de Maracujá, Açúcar, gelo e por último o Whiskey","Com a ajuda de uma bailarina, misture bem."]', '', 'Montado', 'Alcoólico', '/uploads/recipes/RED_MIX_MARACUJA.jpg'),
('Pink Pepper Lemon', '', '[{"name":"Rum Branco","measure":"50 ml"},{"name":"Suco de Limão Siciliano","measure":"1 unidade"},{"name":"Açúcar","measure":"2 colheres de bar"}]', '["Em um copo baixo: adicionar o Limão e o Açúcar.","Encha de gelo, acrescentar a pimenta rosa a gosto, o Rum e mexer.","Decorar com uma pimenta rosa por cima e uma casca torcida de Limão Siciliano."]', 'Pimenta rosa e casca torcida de Limão Siciliano', 'Montado', 'Alcoólico', '/uploads/recipes/PINK_PEPPER_LEMON.png'),
('Rossini', '', '[{"name":"Açúcar","measure":"1 colheres de bar"},{"name":"Suco de Limão","measure":"½ unidade"},{"name":"Morangos picados","measure":"3 unidades"},{"name":"Vinho Frisante ou Prosecco, Espumante","measure":"completar"}]', '["Em um copo baixo: adicionar 3 Morangos picados, uma colher de bar Açúcar e macerar bem.","Acrescentar o ½ unidade Suco de Limão e mexer.","Servir em uma taça e completar com Vinho Frisante ou Prosecco, Espumante gelado.","Decorar com um Morango."]', 'um Morango', 'Montado', 'Alcoólico', '/uploads/recipes/ROSSINI.jpg'),
('ScrewDriver', '', '[{"name":"Vodka","measure":"75 ml"},{"name":"Suco de Laranja","measure":"completar"}]', '["Adicione gelo ao copo e acrescentar a Vodka.","Mexa a Vodka com o gelo para resfriá-la.","Adicionar o Suco de Laranja e mexa novamente.","Decorar com uma fatia de Laranja Bahia."]', '1 fatia de Laranja Bahia', 'Montado', 'Clássico', '/uploads/recipes/SCREWDRIVER.jpg'),
('Kriptonita', '', '[{"name":"Licor de Creme de Menta","measure":"1/2 copo"},{"name":"Vodka","measure":"completar"},{"name":"Pulseiras Luminosas (neon)","measure":"3"}]', '["Em 3 copos de shot: encher até a metade com Licor de Creme de Menta e completar com Vodka.","Decorar com pulseira luminosa (neon)."]', '', 'Montado', 'Shot', '/uploads/recipes/SHOT_KRIPTONITA.jpg'),
('Speed Racer', '', '[{"name":"Vodka","measure":"50 ml"},{"name":"Morangos picados","measure":"2 unidades"},{"name":"Mel","measure":"1 colher de bar"},{"name":"Limão","measure":"1 unidade"},{"name":"Energético","measure":"completar"}]', '["Num copo longo: adicionar 1 Morango picado, 1 colher de bar de mel e macerar.","Gelo intercalado com rodelas de Limão, 1 Morango picado, mais gelo e acrescentar a Vodka.","Completar com energético e decorar com 1 rodela de Limão."]', '1 rodela de Limão', 'Montado', 'Alcoólico', '/uploads/recipes/SPEED_RACER.jpg'),
('Tequila Mix', '', '[{"name":"Tequila","measure":"75 ml"},{"name":"Suco de Pêssego","measure":"100 ml"},{"name":"Suco de Uva","measure":"completar"}]', '["No copo de cocktail: colocar gelo, Suco de Pêssego, Tequila e completar com Suco de uva.","Decorar com um palito com azeitonas e Hortelã."]', 'um palito com azeitonas e Hortelã', 'Montado', 'Alcoólico', '/uploads/recipes/TEQUILA_MIX.jpg'),
('Tequila Sunrise', '', '[{"name":"Tequila Prata","measure":"75 ml"},{"name":"Xarope de Grenadine","measure":"25 ml"},{"name":"Suco de Laranja","measure":"completar"}]', '["Num copo alto: acrescentar o gelo, Tequila e completar com Suco de Laranja.","E depois adicionar o Xarope de Grenadine bem devagar com as costas da colher bailarina.","Decorar com uma casca de Laranja cortada em meia lua e colocar um canudo."]', 'uma casca de Laranja cortada em meia lua', 'Montado', 'Alcoólico', '/uploads/recipes/TEQUILA_SUNRISE.jpg'),
('Spritz', '', '[{"name":"Campari","measure":"50 ml"},{"name":"Vinho Branco","measure":"150 ml"},{"name":"Suco de Laranja","measure":"75 ml"},{"name":"Água com Gás","measure":"100 ml"}]', '["Em uma taça grande: coloque todos os ingredientes e mexer levemente.","Decorar com uma fatia de Laranja."]', 'uma fatia de Laranja', 'Montado', 'Alcoólico', '/uploads/recipes/spritz.jpg'),
('Tequilero Sunrise', '', '[{"name":"Tequila Ouro","measure":"50 ml"},{"name":"Pimenta Dedo de Moça","measure":"1 rodela"},{"name":"Suco de Laranja","measure":"completar"},{"name":"Groselha","measure":"Splash"}]', '["Num copo long: completar com gelo triturado.","Incluir no copo a Tequila, 1 rodela de pimenta dedo de moça e quase completar com Suco de Laranja.","Mexer e acrescentar: um toque de Groselha.","Decorar com uma fatia de Laranja cortada em meia lua e uma pimenta dedo de moça."]', 'uma fatia de Laranja cortada em meia lua e uma pimenta dedo de moça', 'Montado', 'Alcoólico', '/uploads/recipes/TEQUILERO_SUNRISE.jpg'),
('Whiskey Sour de Abacaxi', '', '[{"name":"Whiskey","measure":"50 ml"},{"name":"Suco de Abacaxi","measure":"100 ml"},{"name":"Suco de Limão","measure":"½ unidade"},{"name":"Açúcar","measure":"1 colher de bar"}]', '["Num copo baixo: adicionar todos os ingredientes e mexer.","Decorar com uma fatia de Abacaxi."]', 'uma fatia de Abacaxi', 'Montado', 'Alcoólico', '/uploads/recipes/WHISKY_SOUR_DE_ABACAXI.jpg'),
('Branca de Neve Virgem', '', '[{"name":"Suco de Maçã","measure":"150 ml"},{"name":"Água com Gás ou Club Soda","measure":"completar"}]', '["Em um copo alto (highball), sirva o Suco de Maçã até a metade.","Complete com a Água com Gás ou o Club Soda.","Termine de encher o copo com gelo e pronto."]', '', 'Montado', 'Sem Álcool', '/uploads/recipes/BRANCA_DE_NEVE_VIRGEM.png'),
('Toxic Lemonade Versão 2', '', '[{"name":"Tequila","measure":"75 ml"},{"name":"Limonada","measure":"75 ml"},{"name":"Soda Limonada","measure":"225 ml"}]', '["Misture todos os ingredientes em um copo alto com gelo e sirva."]', '', 'Montado', 'Alcoólico', '/uploads/recipes/TOXIC_LEMONADE_II.png'),
('Toxic Lemonade', '', '[{"name":"Tequila","measure":"75 ml"},{"name":"Limonada (já adoçada)","measure":"75 ml"},{"name":"Soda Limonada","measure":"completar"}]', '["Misture a Tequila e a Limonada em um copo alto com gelo e depois complete com soda."]', '', 'Montado', 'Alcoólico', '/uploads/recipes/TOXIC_LEMONADE.jpg'),
('Drink Exótico', '', '[{"name":"Absinto","measure":"50 ml"},{"name":"Licor de Curaçau Blue","measure":"50 ml"},{"name":"Suco de Maracujá","measure":"20 ml"},{"name":"Groselha","measure":"20 ml"}]', '["Em copo com as 4 pedras de gelo acrescente um a um em ordem, o Suco de Maracujá, a Groselha, o Curaçau Blue e o Absinto.","Ficará um copo todo colorido, sirva com canudinho para ser misturado conforme for bebendo."]', '', 'Montado', 'Alcoólico', '/uploads/recipes/Drink_exotico.png'),
('Hot Smith', '', '[{"name":"Vodka Absolut Peppar","measure":"15 ml"},{"name":"Suco de Morango","measure":"45 ml"},{"name":"Morango","measure":"1 unidade"}]', '["Encha um copo com gelo.","No Suco do gelo coloque o Morango fatiado.","Complete com a mistura da absolut com o Suco de Morango.","Pode substituir a peppar por uma Vodka normal adicionando algumas gotinhas de molho de pimenta tabasco."]', '', 'Montado', 'Alcoólico', '/uploads/recipes/Hot_Smith.png'),
('West Indian Cooler', '', '[{"name":"Suco de Laranja","measure":"80 ml"},{"name":"Suco de Abacaxi","measure":"80 ml"},{"name":"Soda Limonada","measure":"80 ml"}]', '["Num copo de short drink, coloque gelo até a metade.","Adicione o Suco de Laranja e o Suco de Abacaxi, por último, adicione a soda.","Decore com uma fatia de Abacaxi."]', '1 fatia Abacaxi', 'Montado', 'Sem Álcool', '/uploads/recipes/West_Indian_Cooler.jpg'),
('Ana Gisi Tropical', '', '[{"name":"Gin","measure":"80 ml"},{"name":"Energético Tropical","measure":"completar"}]', '["Utilize uma taça grande adicionando gelo, Gin, Energético Tropical para completar e fatias de Laranja, mexa bem com uma colher de bar."]', '3 metades de rodelas Laranja Bahia', 'Montado', 'Alcoólico', '/uploads/recipes/Ana_Gisi_Tropical.png'),
('Chocobomb', '', '[{"name":"Vodka","measure":"30 ml"},{"name":"Licor de Chocolate","measure":"50 ml"},{"name":"Chantily de Chocolate","measure":"completar"}]', '["Despeje em um copo de short drink o Licor de chocolate seguido da Vodka;","Adicione o chantily à vontade até completar o copo;"]', '', 'Montado', 'Alcoólico', '/uploads/recipes/ChocoBomb.png'),
('Tubaína Livre', '', '[{"name":"Cachaça","measure":"50 ml"},{"name":"Tubaína","measure":"1 unidade"},{"name":"Suco de Limão","measure":"1 unidade"}]', '["Encha um copo long drink com gelo, coloque a tubaína até quase completar o copo.","Adicione uma dose de Cachaça, o Suco de Limão e sirva com um canudo."]', '', 'Montado', 'Alcoólico', '/uploads/recipes/Tuba__na_livre.png'),
('Rabo de Galo', '', '[{"name":"Cachaça","measure":"160 ml"},{"name":"Vermute Dry (Seco)","measure":"80 ml"}]', '["Misture os ingredientes num copo com gelo."]', 'Casca de Limão', 'Montado', 'Alcoólico', '/uploads/recipes/Rabo_de_Galo.jpg'),
('Gin Tônica de Morango', '', '[{"name":"Gin Rosê","measure":"50 ml"},{"name":"Morango","measure":"3 unidades"},{"name":"Água Tônica Rosê","measure":"completar"}]', '["Adicione o Gin rosê na taça.","Em seguida, adicione as especiarias e deixe aromatizar durante 1 minuto.","Encha o copo de gelo até a borda (use Morangos fatiados entre as pedrinhas de gelo).","Complete com a Água Tônica rose ou outra de sua preferência."]', 'Morangos e Ramos de Hortelã', 'Montado', 'Alcoólico', '/uploads/recipes/Gin_Tonica_de_Morango.jpg'),
('Long Island Iced Tea Versão 2', '', '[{"name":"Vodka","measure":"10 ml"},{"name":"Tequila","measure":"10 ml"},{"name":"Rum","measure":"10 ml"},{"name":"Cointreau (Triple Sec)","measure":"10 ml"},{"name":"Gin","measure":"10 ml"},{"name":"Suco de Limão","measure":"20 ml"}]', '["Junte todos os ingredientes em um copo alto e complete com Coca Cola."]', '', 'Montado', 'Alcoólico', '/uploads/recipes/Long_Island_Iced_Tea_II.png'),
('Falso Mojito', '', '[{"name":"Cachaça","measure":"50 ml"},{"name":"Açúcar","measure":"2 colher de bar"},{"name":"Suco de Limão","measure":"1 unidade"},{"name":"Hortelã","measure":"12 folhas"},{"name":"Água Tônica","measure":"completar"}]', '["Coloque num copo a Hortelã, o Suco de Limão, o Açúcar e amasse bem...","Adicione a pinga e um pouco de Água Tônica e misture bem.","Complete com o resto da Água Tônica e acrescente o gelo."]', '', 'Montado', 'Alcoólico', '/uploads/recipes/Falso_Mojito.png'),
('Arnold Palmer', '', '[{"name":"Chá Gelado","measure":"75 ml"},{"name":"Limonada","measure":"75 ml"}]', '["Encher um copo alto com gelo picado.","Adicionar todos os ingredientes e mexer.","Decorar com Limão."]', '1 pedaço de Limão', 'Montado', 'Sem Álcool', '/uploads/recipes/Arnold_Palmer.jpg'),
('Whiskey and Cola', '', '[{"name":"Whiskey","measure":"45 ml"},{"name":"Limão","measure":"1 pedaço"},{"name":"Coca Cola","measure":"completar"}]', '["Coloque o Whiskey e o Limão no copo","Colocar o gelo e completa com a coca."]', '', 'Montado', 'Alcoólico', '/uploads/recipes/Whisky_And_Cola.jpg'),
('Brasileirinho (Caipirinha de Melado)', '', '[{"name":"Cachaça","measure":"60 ml"},{"name":"Melaço de Cana","measure":"45 ml"},{"name":"Limão","measure":"1 unidade"}]', '["Descasque o Limão. Fatie a metade dele e transfira para um copo. A outra metade, esprema e coloque o Suco no mesmo copo com as fatias.","Adicione o melado e macere ligeiramente as fatias de Limão, misturando tudo.","Cubra tudo com gelo e complete com a Vodka/Cachaça.","Acrescente um palito/colher/qualquer coisa para mexer, e misture ligeiramente antes de servir. Deixe para quem for beber misturar na hora."]', '', 'Montado', 'Alcoólico', '/uploads/recipes/brasileirinho.png'),
('Canelazo', '', '[{"name":"Cachaça","measure":"50 ml"},{"name":"Água sem Gás","measure":"100 ml"},{"name":"Rapadura","measure":"2 colheres de bar"},{"name":"Canela em pau","measure":"1"},{"name":"Suco de Limão","measure":"2 colheres de bar"}]', '["Ferver a Água junto com a rapadura, a canela e o anis estrelado.","Coar essa mistura quente e juntar com o Limão e a Cachaça.","Servir bem quente."]', '', 'Montado', 'Alcoólico', '/uploads/recipes/Canelazo.jpg'),
('London Spritz', '', '[{"name":"Gin","measure":"40 ml"},{"name":"Aperol","measure":"20 ml"},{"name":"Água Tônica","measure":"60 ml"},{"name":"Prosecco, Espumante","measure":"100 ml"}]', '["Coloque uma fatia fina de Limão em uma taça e coloque os ingredientes.","Para finalizar, complete a taça com gelo."]', '', 'Montado', 'Alcoólico', '/uploads/recipes/London_Spritz.png'),
('Black Velvet', '', '[{"name":"Brutt, Espumante","measure":"80 ml"},{"name":"Cerveja Stout","measure":"completar"}]', '["Adicione, em um copo bem gelado, o espumante e complete o conteúdo com a cerveja stout.","Você pode fazer essa mistura delicadamente, com a ajuda das costas de uma colher."]', '', 'Montado', 'Alcoólico', '/uploads/recipes/Black_Velvet.png'),
('Negroni Versão 2', '', '[{"name":"Campari","measure":"30 ml"},{"name":"Vermute Rosso (Doce)","measure":"30 ml"},{"name":"Gin","measure":"45 ml"},{"name":"Suco de Laranja","measure":"1 gomo"}]', '["Coloque um gomo de Laranja em um copo (esprema a fruta para sair o suco) e complete com gelo.","Coloque o vermute, o Campari, o Gin e mexa.","Passa a casca de Laranja na borda do copo."]', 'Casca de Laranja', 'Montado', 'Alcoólico', '/uploads/recipes/NEGRONI_III.png'),
('Mojito com Sprite', '', '[{"name":"Rum","measure":"50 ml"},{"name":"Hortelã","measure":"4 folhas"},{"name":"Açúcar","measure":"1 colher de bar"},{"name":"Sprite","measure":"completar"}]', '["Pique a Hortelã e coloque num copo.","Acrescente o Açúcar, a dose de Rum e misture.","Coloque o gelo e o sprite até completar o copo, para finalizar, usa uma folha Hortelã para esfregar na borda do copo."]', 'uma folha Hortelã', 'Montado', 'Alcoólico', '/uploads/recipes/Mojito_Com_Sprite.jpg'),
('Gin Tônica de Maçã Verde', '', '[{"name":"Gin","measure":"50 ml"},{"name":"Xarope de Maçã Verde","measure":"20 ml"},{"name":"Suco de Limão","measure":"10 ml"},{"name":"Água Tônica","measure":"completar"}]', '["Cuidadosamente, encha uma taça de Vinho tinto com gelo até a borda.","Coloque nesta ordem: o Gin, o Xarope de Maçã Verde e o Suco de Limão.","Complete o drink com Água Tônica. Mexa cuidadosamente até que todos os ingredientes estejam incorporados.","Finalize o copo com uma rodela de Limão e sirva."]', 'uma rodela de Limão', 'Montado', 'Alcoólico', '/uploads/recipes/GIN_TONICA_DE_MACA_VERDE.jpg'),
('Mandarina Tropical', '', '[{"name":"Gin","measure":"50 ml"},{"name":"Suco de Tangerina","measure":"60 ml"},{"name":"Manjericão","measure":"10 folhas"},{"name":"Açúcar","measure":"1 colher de bar"},{"name":"Tangerina (Mexerica)","measure":"2 gomos"},{"name":"Água com Gás","measure":"completar"}]', '["Em primeiro lugar, adicione os ingredientes Gin, Suco natural de Tangerina, folhas de manjericão fresco e o Açúcar em um copo grande, sempre usando um dosador, misture os ingredientes, depois adicione gelo, então mexa novamente e complete com um pouquinho"]', '2 fatias de Tangerina e manjericão', 'Montado', 'Alcoólico', '/uploads/recipes/Mandarina_Tropical.png'),
('Caipijurupinga de Morango', '', '[{"name":"Jurupinga","measure":"100 ml"},{"name":"Morangos","measure":"6 unidades"},{"name":"Suco de Limão","measure":"½ unidade"},{"name":"Açúcar","measure":"1 colher de bar"}]', '["Em um copo: (250ml), coloque os 6 Morangos cortados ao suco, 1 colher de bar de Açúcar, ½ unidade Suco de Limão e macere.","Acrescente a Jurupinga e misture bem.","Inclua o gelo picado até em cima.","Decorar usando: 1 Morango na borda, 1 canudo e 1 ramo Hortelã na borda."]', '1 ramo Hortelã e 1 Morango na borda', 'Montado', 'Alcoólico', '/uploads/recipes/Caipijurupinga_morango.jpg'),
('Jurugin', '', '[{"name":"Gin","measure":"50 ml"},{"name":"Suco de Maçã","measure":"50 ml"},{"name":"Jurupinga","measure":"completar"},{"name":"Limão Taiti","measure":"½ unidade"},{"name":"Açúcar Mascavo","measure":"1 colher de bar"}]', '["Em uma taça de Gin, passe Limão e Açúcar Mascavo na borda","Coloque o Limão em pedaços na taça e acrescente o Açúcar Mascavo, macere levemente, acrescente o Gin, adicione o Suco de Maçã e misture.","Coloque pedras de gelo até em cima e complete com Jurupinga","Misture levemente e decore com uma fatia de Limão e uma de Maçã."]', 'uma fatia de Limão e uma de Maçã', 'Montado', 'Alcoólico', '/uploads/recipes/Jurugin.png'),
('Condessa', '', '[{"name":"Vodka","measure":"50 ml"},{"name":"Água de Coco","measure":"50 ml"}]', '["Adicione os ingredientes em um copo e misture todos os ingredientes com o canudo.","Use coco em lascas para decorar","Se tiver coco fresco em casa, corte em fatias finas e jogue ao fundo."]', 'Coco em lascas', 'Montado', 'Alcoólico', '/uploads/recipes/Condessa.png'),
('Tequila Sunrise Versão 2', '', '[{"name":"Tequila","measure":"100 ml"},{"name":"Suco de Laranja","measure":"175 ml"},{"name":"Xarope de Grenadine","measure":"50 ml"}]', '["Coloque os cubos de gelo em um copo long drink e adicione a Tequila e o Suco de Laranja.","Acrescente os fios de Xarope de Grenadine e deixe descansar no fundo do copo.","Decore com uma rodela de Laranja e uma Cereja fresca."]', 'uma rodela de Laranja e uma Cereja', 'Montado', 'Alcoólico', '/uploads/recipes/Tequila_Sunrise_II.png'),
('Gin Orange', '', '[{"name":"Gin","measure":"50 ml"},{"name":"Xarope de Tangerina","measure":"30 ml"},{"name":"Energético Tropical","measure":"completar"},{"name":"Tangerina","measure":"6 gomos"}]', '["Em uma taça previamente gelada, adicione o Gin, o Xarope de Tangerina, mexa para harmonizar, adicione o gelo, os gomos de Tangerina, complete com o Energético tropical, mexa suavemente de baixo para cima, guarnição alecrim e gomo de Tangerina."]', '1 ramo de alecrim e gomo de Tangerina', 'Montado', 'Alcoólico', '/uploads/recipes/Gin_Orange.png'),
