('Lagoa Beats', '', '[{"name":"Vodka","measure":"50 ml"},{"name":"Licor de Curaçau Blue","measure":"30 ml"},{"name":"Suco de Limão","measure":"½ unidade"},{"name":"Limão","measure":"2 rodelas"},{"name":"Skol Beats Senses","measure":"completar"}]', '["Primeiro prepare a taça, passe Leite Condensado e depois passe no coco ralado, para gerar a borda da taça.","Adicione gelo picado a taça, as rodelas de Limão, o Suco de Limão, o Licor Curaçau Blue complete com a Skol Beats Senses."]', 'Leite Condensado e Coco Ralado (borda)', 'Montado', 'Alcoólico', '/uploads/recipes/LAGOA_BEATS.jpg'),
('Gin Blue Lagoon', '', '[{"name":"Gin","measure":"50 ml"},{"name":"Xarope de Curaçau Blue","measure":"30 ml"},{"name":"Água Tônica","measure":"completar"}]', '["Em uma taça previamente gelada, adicione o Gin, e os cravos da índia, e o Xarope de Curaçau Blue Laranja, mexa para harmonizar, adicione o gelo e a rodela de Laranja, complete com a Água Tônica, mexa suavemente de baixo para cima, guarnição meia rodela de"]', '1/2 rodela de Laranja com cravos', 'Montado', 'Alcoólico', '/uploads/recipes/GIN_BLUE_LAGOON.png'),
('Passion Fruit Gin', '', '[{"name":"Gin","measure":"50 ml"},{"name":"Xarope de Gengibre","measure":"30 ml"},{"name":"Maracujá","measure":"½ unidade"},{"name":"Energético Tropical","measure":"completar"},{"name":"Pimenta Rosa","measure":"1 porção"}]', '["Em uma taça previamente gelada, adicione o Gin, o Xarope de Gengibre, a Polpa de Maracujá, a porção de pimenta rosa, mexa para harmonizar.","Adicione o gelo e complete com o Energético tropical, mexa suavemente de baixo para cima, guarnição ramo de alecrim."]', '1 ramo de alecrim', 'Montado', 'Alcoólico', '/uploads/recipes/PASSION_FRUIT_GIN.jpg'),
('Tropical Orange Gin', '', '[{"name":"Gin","measure":"50 ml"},{"name":"Xarope de Limão Siciliano","measure":"30 ml"},{"name":"Suco de Laranja","measure":"1 unidade"},{"name":"Laranja","measure":"2 rodelas"},{"name":"Energético Tropical","measure":"completar"}]', '["Em uma taça previamente gelada, adicione o Gin, o Xarope de Limão Siciliano, o Suco da Laranja, mexa para harmonizar.","Adicione o gelo e as rodelas de Laranja na lateral da taça, complete com o Energético tropical."]', 'ramo de alecrim', 'Montado', 'Alcoólico', '/uploads/recipes/TROPICAL_ORANGE_GIN.jpg'),
('Soda Italiana de Tangerina', '', '[{"name":"Xarope de Tangerina","measure":"75 ml"},{"name":"Água com Gás","measure":"completar"}]', '["Em uma taça adicione o Xarope de Tangerina, gelo e complete com a Água com Gás, guarnição sol feito de Laranja."]', 'Sol de Laranja', 'Montado', 'Sem Álcool', '/uploads/recipes/SODA_ITALIANA_DE_TANGERINA.jpg'),
('Gin de Manga', '', '[{"name":"Gin","measure":"50 ml"},{"name":"Xarope de Limão Siciliano","measure":"30 ml"},{"name":"Manga","measure":"80 g"},{"name":"Energético Manga","measure":"completar"}]', '["Em uma taça previamente gelada, adicione o Gin, o Xarope de Limão Siciliano zero, mexa para harmonizar.","Adicione o gelo e uma manga fatiada, complete com o Energético Manga, guarnição ramo de alecrim."]', 'ramo de alecrim', 'Montado', 'Alcoólico', '/uploads/recipes/GIN_DE_MANGA.jpg'),
('Caipijurupinga', '', '[{"name":"Cachaça","measure":"25 ml"},{"name":"Leite Condensado","measure":"25 ml"},{"name":"Suco de Limão","measure":"1 unidade"},{"name":"Jurupinga","measure":"completar"}]', '["Espremer o Limão no copo, adicionar Jurupinga a gosto, adicionar a Cachaça e o Leite Condensado e mexer","Completar com gelo e decorar com uma fatia e alguns pedacinhos de Limão."]', 'uma fatia e alguns pedacinhos de Limão', 'Montado', 'Alcoólico', '/uploads/recipes/Caipijurupinga.png'),
('Gremlins Mojito', '', '[{"name":"Rum","measure":"50 ml"},{"name":"Suco de Limão","measure":"25 ml"},{"name":"Água com Gás","measure":"25 ml"},{"name":"Hortelã","measure":"10 folhas"},{"name":"Açúcar","measure":"1 colher de bar"}]', '["Coloque todos os ingredientes num copo longo.","Misture bem e pronto."]', '', 'Montado', 'Alcoólico', '/uploads/recipes/GREMLINS_MOJITO.jpg'),
('Jurupinga On The Beach', '', '[{"name":"Jurupinga","measure":"150 ml"},{"name":"Licor de Pêssego","measure":"25 ml"},{"name":"Xarope de Grenadine","measure":"2 colher de bar"},{"name":"Açúcar vermelho","measure":""},{"name":"Suco de Laranja","measure":"completar"}]', '["Em uma taça longa (500ml): passe Limão na borda, grude Açúcar vermelho na borda, acrescente as 6 pedras de gelo, a Jurupinga, o Licor de Pêssego, complete com Suco de Laranja e misture levemente.","Acrescente devagar o Xarope de Grenadine","Decore usando: Cereja, rodela de Laranja na borda e canudo."]', 'Cereja, rodela de Laranja na borda', 'Montado', 'Alcoólico', '/uploads/recipes/Jurupinga_on_the_Beach.png'),
('Gin Tangerina Tropical', '', '[{"name":"Gin","measure":"50 ml"},{"name":"Xarope de Tangerina","measure":"30 ml"},{"name":"Tangerina","measure":"6 gomos"},{"name":"Energético Tropical","measure":"completar"}]', '["Em uma taça previamente gelada, adicione o Gin, o Xarope de Tangerina, mexa para harmonizar, adicione o gelo os gomos de Tangerina.","Complete com o Energético tropical, mexa suavemente de baixo para cima, guarnição alecrim e gomo de Tangerina."]', '1 ramo de alecrim e gomo de tangerina', 'Montado', 'Alcoólico', '/uploads/recipes/GIN_TANGERINA_TROPICAL.jpg'),
('Blue Lagoon Gin & Tônica', '', '[{"name":"Gin","measure":"50 ml"},{"name":"Xarope de Curaçau Blue","measure":"30 ml"},{"name":"Suco de Limão Siciliano","measure":"½ unidade"},{"name":"Água Tônica sabor 3 limões","measure":"completar"}]', '["Em uma taça previamente gelada, o Gin, o Suco do Limão Siciliano, mexa para harmonizar.","Adicione o gelo, meia rodela de Laranja com cravos, a Água Tônica, finalize com o Xarope de Curaçau Blue, mexa suavemente de baixo para cima."]', '', 'Montado', 'Alcoólico', '/uploads/recipes/BLUE_LAGOON_GIN_e_TONICA.png'),
('Isla San Andres', '', '[{"name":"Rum","measure":"50 ml"},{"name":"Água de Coco","measure":"50 ml"},{"name":"Cointreau (Triple Sec)","measure":"25 ml"},{"name":"Licor de Curaçau Blue","measure":"10 ml"},{"name":"Suco de Abacaxi","measure":"completar"}]', '["Em um copo alto com gelo, adicione o Rum, o Curaçau Blue, a Água de Coco, o Cointreau (Triple Sec) e por fim o Suco de Abacaxi.","Misture gentilmente com uma colher e decore com uma fatia de Limão Siciliano!"]', 'uma fatia de Limão Siciliano', 'Montado', 'Alcoólico', '/uploads/recipes/ISLA_SAN_ANDRES.png'),
('Tangin Tropical', '', '[{"name":"Gin","measure":"50 ml"},{"name":"Xarope de Tangerina","measure":"30 ml"},{"name":"Energético Tropical","measure":"completar"},{"name":"Tangerica (Mexerica)","measure":"5 gomos"}]', '["Em uma taça previamente gelada, adicione o Gin, o Xarope de Tangerina, mexa para harmonizaz.","Adicione o gelo, os gomos de Tangerina (de um corte neles para soltar o sabor), complete com o Energético tropical.","Mexa suavemente de baixo para cima, guarnição gomo do Tangerina."]', 'gomo do Tangerina', 'Montado', 'Alcoólico', '/uploads/recipes/TANGIN_TROPICAL.jpg'),
('Aperol Sprintz Rosé', '', '[{"name":"Aperol","measure":"30 ml"},{"name":"Suco de Limão","measure":"30 ml"},{"name":"Suco de Maracujá","measure":"90 ml"},{"name":"Rosé, Espumante","measure":"60 ml"},{"name":"Açúcar","measure":"4 colheres de bar"}]', '["Coloque os sucos, o Aperol e a Açúcar em uma caneca até que seja dissolvido. sirva em um copo largo com gelo.","Adicione o espumante misturando gentilmente, decore e está pronto!"]', '', 'Montado', 'Alcoólico', '/uploads/recipes/aperol_sprintz_rose.png'),
('Whiskey Highball', '', '[{"name":"Whiskey","measure":"50 ml"},{"name":"Xarope de Gengibre","measure":"30 ml"},{"name":"Limão","measure":"2 rodelas"},{"name":"Água Tônica, Água de Coco ou guaraná","measure":"completar"}]', '["Em um copo alto com gelo, coloque o Whiskey, o Xarope e as fatias de frutas e misture gentilmente.","Torça um pedaço da casca da fruta sobre o copo, jogue-a dentro do copo (twist) e está pronto!"]', '1 twist', 'Montado', 'Alcoólico', '/uploads/recipes/WHISKY_HIGHBALL.jpg'),
('Negroni Sbagliato', '', '[{"name":"Campari","measure":"50 ml"},{"name":"Vermute Rosso (Doce)","measure":"50 ml"},{"name":"Prosecco, Espumante","measure":"50 ml"}]', '["Misture os ingredientes e sirva em um copo baixo com muito gelo e meia rodela de Laranja."]', '½ rodela de Laranja', 'Montado', 'Alcoólico', '/uploads/recipes/NEGRONI_SBAGLIATO.png'),
('Champagne Sunrise', '', '[{"name":"Suco de Laranja","measure":"60 ml"},{"name":"Licor de Groselha","measure":"30 ml"},{"name":"Moscatel, Espumante","measure":"completar"}]', '["Coloque os ingredientes em uma taça, complete com espumante de sua preferencia e está pronto!"]', '', 'Montado', 'Alcoólico', '/uploads/recipes/CHAMPAGNE_SUNRISE.png'),
('Rossini Versão 2', '', '[{"name":"Prosecco, Espumante","measure":"100 ml"},{"name":"Morango","measure":"1 unidade"},{"name":"Açúcar","measure":"1 colher de bar"}]', '["Em um bowl, amasse bem o Morango (pode usar um mixer). Se preferir um drink mais doce, acrescente um pouco de Açúcar. Em uma taça, misture o Morango com o espumante de sua preferencia, mexendo sem muita força.","Para decorar, coloque um Morango na taça."]', 'um Morango', 'Montado', 'Alcoólico', '/uploads/recipes/ROSSINI1_II.jpg'),
('Água de Valença', '', '[{"name":"Vodka","measure":"30 ml"},{"name":"Prosecco, Espumante","measure":"100 ml"},{"name":"Suco de Laranja","measure":"200 ml"},{"name":"Laranjas picadas","measure":"2 unidades"},{"name":"Limão picado","measure":"1 unidade"}]', '["Retire a casca da Laranja e reserve. Em uma jarra grande, misture todos os ingredientes mexendo um pouco.","Use a criatividade: Decore a jarra com a casca da Laranja e sirva!"]', 'casca da Laranja', 'Montado', 'Alcoólico', '/uploads/recipes/AGUA_DE_VALENCA.jpg'),
('The Godfather', '', '[{"name":"Whiskey","measure":"50 ml"},{"name":"Amaretto","measure":"25 ml"}]', '["Em um copo old fashioned coloque gelo, o Whiskey e o Licor e misture suavemente. Quanto melhor a qualidade do Whiskey, melhor será seu drink."]', '', 'Montado', 'Alcoólico', '/uploads/recipes/THE_GODFATHER.jpg'),
('Café da Noite', '', '[{"name":"Gin","measure":"50 ml"},{"name":"Suco de Laranja","measure":"50 ml"},{"name":"Café Espresso pleno TRES","measure":"1 capsula"}]', '["Coloque todos os ingredientes em um copo de drink. Finalize com muito gelo."]', '', 'Montado', 'Alcoólico', '/uploads/recipes/CAFE_DA_NOITE.png'),
('Gin & Juice', '', '[{"name":"Gin","measure":"50 ml"},{"name":"Suco de Laranja","measure":"100 ml"},{"name":"Suco de Abacaxi","measure":"50 ml"}]', '["Coloque gelo no copo. Adicione o Gin e os sucos e finalize com um twist de Limão para decoração.","Também é possível variar as frutas utilizadas, criando assim sabores únicos de Gin & juice!!"]', 'Twist de Limão', 'Montado', 'Alcoólico', '/uploads/recipes/Gin___Juice.png'),
('Gin Romana', '', '[{"name":"Gin","measure":"60 ml"},{"name":"Romã","measure":"4 colheres bar"},{"name":"Manjerição","measure":"1 ramo"},{"name":"Água Tônica","measure":"completar"}]', '["Adicione as sementes de Romã em uma taça balloon e amasse levemente, para soltar um pouco do líquido e o aroma.","Separe as folhas do cabo do manjericão e coloque-as na taça. Some o Gin, adicione bastante gelo e complete com Água Tônica."]', '', 'Montado', 'Alcoólico', '/uploads/recipes/GIN_ROMANA.png'),
('Aperol Fast', '', '[{"name":"Vodka","measure":"80 ml"},{"name":"Aperol","measure":"80 ml"},{"name":"Laranja","measure":"1 unidade"},{"name":"Água Tônica","measure":"completar"}]', '["Adicione um copo o gelo, o Aperol, a Vodka. Corte a Laranja em pequenas fatias, acrescente para decorar seu drink e esprema algumas fatias para adicionar mais sabor. Finalize com a tônica e misture suavemente."]', '', 'Montado', 'Alcoólico', '/uploads/recipes/Aperol_fast.png'),
('Shark Attack', '', '[{"name":"Rum","measure":"50 ml"},{"name":"Vodka","measure":"50 ml"},{"name":"Licor de Curaçau Blue","measure":"15 ml"},{"name":"Xarope de Grenadine","measure":"20 ml"},{"name":"Xarope de Açúcar","measure":"20 ml"}]', '["Em um copo com gelo, adicione primeiro o Rum, depois o Curaçau e a Vodka, então misture o xarope.","Termine despejando o Xarope de Grenadine e está pronto!"]', '', 'Montado', 'Alcoólico', '/uploads/recipes/SHARK_ATTACK.jpg'),
('Moji Tangerina', '', '[{"name":"Rum Prata","measure":"50 ml"},{"name":"Tangerina","measure":"1 unidade"},{"name":"Hortelã","measure":"6 folhas"},{"name":"Açúcar","measure":"2 colheres de bar"},{"name":"Água Tônica","measure":"completar"}]', '["Separe a Tangerina em gomos e macere junto com a Hortelã em uma coqueteleira.","Adicione o Açúcar, o gelo, o Rum e bata suavemente.","Sirva em um copo e complete com a Água Tônica."]', '', 'Batido', 'Alcoólico', '/uploads/recipes/MOJI_TANGERINA.jpg'),
('Red Citrus', '', '[{"name":"Whiskey","measure":"50 ml"},{"name":"Suco de Laranja","measure":"15 ml"},{"name":"Água Tônica","measure":"completar"}]', '["Coloque gelo em um copo alto.","Adicione o Whiskey, o Suco de Laranja e complete com a tônica.","Decore com uma rodela de Laranja."]', '1 rodela de Laranja', 'Montado', 'Alcoólico', '/uploads/recipes/RED_CITRUS.png'),
('Catu Tônica', '', '[{"name":"Catuaba","measure":"150 ml"},{"name":"Água Tônica","measure":"50 ml"},{"name":"Limão","measure":"1 unidade"}]', '["Corte o Limão em 8 partes e esprema 2 partes em um copo.","Encha o copo com gelo e decore com o Limão.","Adicione a catuaba e a Água Tônica e misture suavemente com um canudo.","Experimente utilizar outras frutas cítricas (como Laranja ou Tangerina)."]', '', 'Montado', 'Alcoólico', '/uploads/recipes/CATU_TONICA.jpg'),
('B. Tônic', '', '[{"name":"Gin","measure":"50 ml"},{"name":"Suco Limão","measure":"10 ml"},{"name":"Tangerina","measure":"2 rodelas"}]', '["Misture o Gin e o Suco de Limão","Decore o copo com gelo e as fatias de Tangerina","Sirva o Gin com Limão e finalize com as rosas e o ramo de alecrim."]', '1 ramo de alecrim e Rosas de ameixa', 'Montado', 'Alcoólico', '/uploads/recipes/B._tonic.png'),
('Catineja', '', '[{"name":"Catuaba","measure":"50 ml"},{"name":"Cerveja","measure":"completar"}]', '["Adicione a catuaba.","Complete o copo com a cerveja de sua preferencia.","Como não vai gelo nessa bebida é importante que todos os ingredientes estejam gelados."]', '', 'Montado', 'Alcoólico', '/uploads/recipes/CATINEJA.png'),
('Shirley Temple', '', '[{"name":"Xarope de Morango","measure":"15 ml"},{"name":"Xarope de Gengibre","measure":"15 ml"},{"name":"Água com Gás","measure":"completar"}]', '["Em copo comprido coloque os xaropes, gelo e complete com a Água com Gás.","Decore pondo 2 Cerejas em um palito e está pronto!"]', '2 Cerejas num palito', 'Montado', 'Sem Álcool', '/uploads/recipes/Shirley_Temple.jpg'),
('Highball', '', '[{"name":"Gin","measure":"50 ml"},{"name":"Xarope de Menta","measure":"15 ml"},{"name":"Vodka","measure":"25 ml"},{"name":"Suco de Limão","measure":"50 ml"},{"name":"Xarope de Açúcar","measure":"30 ml"},{"name":"Água Tônica","measure":"75 ml"}]', '["Misture todos os ingredientes no seu highball suavemente com algumas pedras de gelo. Em seguida adicione o Xarope de Menta.","Decore com algumas folhas de menta."]', 'Folhas de menta ou Hortelã', 'Montado', 'Alcoólico', '/uploads/recipes/Highball.jpg'),
('Pussy Foot', '', '[{"name":"Vodka","measure":"75 ml"},{"name":"Suco de Laranja","measure":"75 ml"},{"name":"Suco de Cranberry","measure":"75 ml"}]', '["Vire a Vodka em um copo com gelo e em seguida adicione os dois sucos."]', '', 'Montado', 'Alcoólico', '/uploads/recipes/Pussy_Foot.png'),
('Hepy', '', '[{"name":"Gin","measure":"50 ml"},{"name":"Xarope de Tangerina","measure":"30 ml"},{"name":"Xarope de Limão","measure":"20 ml"},{"name":"Água Tônica","measure":"completar"}]', '["Ponha o gelo na taça, adicione o Gin, os xaropes, complete com a Água Tônica e termine enfeitando com as frutas!"]', '2 meias luas de Limão Siciliano', 'Montado', 'Alcoólico', '/uploads/recipes/hepy.png'),
('Fizz de Morango', '', '[{"name":"Gin","measure":"45 ml"},{"name":"Suco de Limão","measure":"15 ml"},{"name":"Xarope de Açúcar","measure":"10 ml"},{"name":"H2OH","measure":"45 ml"},{"name":"Xarope de Morango","measure":"30 ml"}]', '["Adicione todos os ingredientes menos o Gin e o Xarope de Morango em uma taça com gelo e mexa.","Em um copo separado misture o Gin e o Xarope de Morango e derrame por cima para dar o efeito da foto."]', '', 'Montado', 'Alcoólico', '/uploads/recipes/Fizz_de_Morango.png'),
('Pink Lemonade', '', '[{"name":"Vodka","measure":"120 ml"},{"name":"Água com Gás","measure":"500 ml"},{"name":"Xarope de Groselha","measure":"50 ml"},{"name":"Açúcar","measure":"2 colheres de bar"},{"name":"Suco de Limão","measure":"3 unidades"}]', '["Em uma jarra adicione água, xarope, Suco de Limão, Vodka e Açúcar e misture bem.","Depois adicione o gelo e as rodelas de Limão em um copo e sirva o drink."]', 'Rodelas de Limão dentro copo', 'Montado', 'Alcoólico', '/uploads/recipes/Pink_Lemonade_II.png'),
('Dawa', '', '[{"name":"Cachaça","measure":"100 ml"},{"name":"Suco de Limão","measure":"50 ml"},{"name":"Limão Siciliano","measure":"1 unidade"},{"name":"Açúcar Mascavo","measure":"2 colher de bar"},{"name":"Mel","measure":"2 colher de bar"}]', '["Parta o Limão em 8 partes iguais e os posicione em um copo, adicione o Açúcar Mascavo e macere.","Acrescente o Suco de Limão, a Cachaça e coloque gelo até perto da borda.","Misture levemente com o canudo e adicione o mel.","Continue misturando a bebida com o canudo enquanto bebe para manter o aspecto adocicado do seu drink."]', '', 'Montado', 'Alcoólico', '/uploads/recipes/Dawa.png'),
('Tchay', '', '[{"name":"Vodka","measure":"120 ml"},{"name":"Energético Maçã Verde","measure":"100 ml"},{"name":"Xarope de Maçã Verde","measure":"50 ml"},{"name":"Xarope de Grenadine","measure":"5 ml"}]', '["Encha um copo de gelo.","Coloque o Xarope de Maçã Verde e adicione lentamente o energético e a Vodka.","Separadamente misture a Vodka e a Xarope de Grenadine e em seguida adicione ao copo."]', '', 'Montado', 'Alcoólico', '/uploads/recipes/TCHAY.jpg'),
('Soda de Frutas Vermelhas', '', '[{"name":"Xarope de Cranberry","measure":"60 ml"},{"name":"Água com Gás","measure":"completar"},{"name":"Morango","measure":"2 unidades"}]', '["Em uma taça ou copo de sua preferência, adicione o gelo juntamente com fatias finas de Morango. Logo após acrescente o Xarope de Morango, complete com Água com Gás.","Observação: Caso opte por modificar a receita para uma bebida alcoólica poderá ser acrescentado 50 ml do seu destilado escolhido."]', '3 Morangos e 1 Cereja', 'Montado', 'Sem Álcool', '/uploads/recipes/SODA_ITALIANA_DE_MORANGO.jpg'),
('Coco Gin', '', '[{"name":"Gin","measure":"70 ml"},{"name":"Rum Malibu","measure":"30 ml"},{"name":"Leite de Coco","measure":"30 ml"},{"name":"Água de Coco congelada em cubos","measure":"1 unidade"},{"name":"Soda Limonada","measure":"completar"}]', '["Encha a taça até a metade com os cubos de gelo, coloque o Gin, Rum, Leite de Coco e misture com uma colher bailarina.","Complete a taça com gelo, posicione pedaços de coco entre os gelos. Complete a taça com a soda.","Coloque pedaços de coco como guarnição."]', 'pedaços de coco', 'Montado', 'Alcoólico', '/uploads/recipes/COCO_GIN.png'),
('Kir Royal Versão 2', '', '[{"name":"Xarope de Frutas Vermelhas","measure":"15 ml"},{"name":"Brutt, Espumante","measure":"completar"}]', '["Em uma taça flute de champanhe adicione o Xarope de Frutas Vermelha, e depois complete com o espumante de sua preferencia, finalize com o Morango fatiado."]', '1 Morango fatiado', 'Montado', 'Alcoólico', '/uploads/recipes/KIR_ROYAL_II.jpg'),
('Gin Tônica Limão Siciliano', '', '[{"name":"Gin","measure":"50 ml"},{"name":"Xarope de Limão Siciliano","measure":"30 ml"},{"name":"Suco Limão Siciliano","measure":"½ unidade"},{"name":"Água Tônica Sabor 3 Limões","measure":"completar"}]', '["Gele a taça, o Gin, o Xarope de Limão Siciliano, o Limão Siciliano, mexa para harmonizar.","Adicione o gelo, uma rodela de Limão Siciliano, complete com a Água Tônica, mexa suavemente de baixo para cima.","Guarnição com a flor feita com a casca do Limão."]', '1 flor da casca do Limão Siciliano', 'Montado', 'Alcoólico', '/uploads/recipes/GIN_TONICA_LIMAO_SICILIANO.jpg'),
('Gin Verão Amarelo', '', '[{"name":"Gin","measure":"50 ml"},{"name":"Licor de Tangerina","measure":"50 ml"},{"name":"Laranja","measure":"1 unidade"},{"name":"Água Tônica","measure":"completar"}]', '["Macerar a Laranja e colocar no fundo da taça. Preencher com a dose do Gin e bastante gelo.","Quase complete com a Água Tônica e após, entorne a dose do Licor de Tangerina sobre o topo do gelo dentro da taça."]', 'Zimbro e anis estrelado', 'Montado', 'Alcoólico', '/uploads/recipes/Gin_Verao_Amarelo.jpg'),
('Maracajá Tropical', '', '[{"name":"Gin","measure":"60 ml"},{"name":"Polpa de Maracujá","measure":"1 colher de bar"},{"name":"Limão Siciliano","measure":"3 rodelas"},{"name":"Energético Tropical","measure":"completar"}]', '["Em uma taça grande, adicione gelo, rodelas de Limão e Gin.","Após adicionar os ingredientes no tópico acima, adicione uma colher de Polpa de Maracujá.","Complete o copo com o Energético Tropical e com uma colher bailarina mexa suavemente."]', '', 'Montado', 'Alcoólico', '/uploads/recipes/Maracaja_Tropical.jpg'),
('Cachaça com Energético Açaí', '', '[{"name":"Cachaça","measure":"50 ml"},{"name":"Suco de Limão","measure":"½ unidade"},{"name":"Energético Açaí","measure":"completar"}]', '["Adicionar gelo ao copo, a Cachaça, o Suco do Limão e mexa com uma colher bailarina","Complete o copo com Energético açaí","Mexa suavemente com uma colher bailarina e sirva!"]', '', 'Montado', 'Alcoólico', '/uploads/recipes/Cachaca_energetico_Acai.png'),
('Groselha de Coco', '', '[{"name":"Rum Malibu","measure":"70 ml"},{"name":"Xarope de Morango","measure":"5 ml"}]', '["Misturar no próprio copo de shot."]', '', 'Montado', 'Shot', '/uploads/recipes/Shot_Groselha_de_Coco.jpg'),
