('Representante do Pecado', '', '[{"name":"Gin","measure":"25 ml"},{"name":"Suco de Limão","measure":"40 ml"},{"name":"Soda Limonada","measure":"completar"}]', '["Adicione as bebidas na ordem acima, misture bem e enfeite com as fatias de Maçã."]', '3 a 4 fatias de Maçã (finas)', 'Montado', 'Alcoólico', '/uploads/recipes/Representante_do_pecado.png'),
('Blue Sky', '', '[{"name":"Xarope de Curaçau Blue","measure":"50 ml"},{"name":"Suco de Laranja Bahia","measure":"1 unidade"},{"name":"Água com Gás","measure":"completar"}]', '["Em uma taça adicione o Xarope e o Suco de Laranja","Adicione gelo e complete de Água com Gás. Misture levemente e sirva!"]', '', 'Montado', 'Sem Álcool', '/uploads/recipes/Blue_Sky__sem_alcool_.jpg'),
('Bujito', '', '[{"name":"Cachaça","measure":"60 ml"},{"name":"Suco de Limão","measure":"20 ml"},{"name":"Hortelã","measure":"8 folhas"},{"name":"Açúcar","measure":"3 colheres de bar"},{"name":"Água com Gás","measure":"completar"}]', '["Em copo tipo americano alto, macere a Hortelã com o Suco de Limão e o Açúcar. Adicione gelo e finalize a Água com Gás. Decore com Hortelã fresca e polvilhe Açúcar de confeiteiro."]', 'Ramo de Hortelã', 'Montado', 'Alcoólico', '/uploads/recipes/BUJITO.png'),
('Caipiroska de Cerveja', '', '[{"name":"Vodka","measure":"50 ml"},{"name":"Suco de Limão","measure":"1 unidade"},{"name":"Açúcar","measure":"1 colher de bar"},{"name":"Cerveja","measure":"completar"}]', '["Comece preparando a caipirinha: esprema o Suco do Limão e retire as sementes. Junte o Açúcar e a Vodka e misture até dissolver o Açúcar. Não precisa macerar os gomos do Limão como na caipiroska tradicional porque a cerveja já é Suco amarga.","Molhe as bordas com o Limão já espremido e mergulhe no sal.","Preencha cada taça/copo com gelo e derrame metade da caipiroska em cada e complete cada uma com a cerveja e sirva de imediato."]', '', 'Montado', 'Alcoólico', '/uploads/recipes/Caipiroska_de_Cerveja.png'),
('Caipirinha Marino', '', '[{"name":"Vodka","measure":"50 ml"},{"name":"Xarope de Curaçau Blue","measure":"30 ml"},{"name":"Licor de Curaçau Blue","measure":"20 ml"},{"name":"Abacaxi","measure":"1 fatia"},{"name":"Açúcar","measure":"1 colher de bar"},{"name":"Gengibre","measure":"1 fatia"}]', '["Em um copo, coloque o Abacaxi cortado, o gengibre fatiado, o Açúcar e as folhas Hortelã, limpas.","Amasse, complete o copo com gelo, acrescente a Cachaça, o Curaçau Blue e finalize com o Xarope de Curaçau Blue.","Decore o drinque com um ramo Hortelã."]', '1 ramo Hortelã (guarnição)', 'Montado', 'Alcoólico', '/uploads/recipes/Caipirinha_Marino.jpg'),
('Bullfrog', '', '[{"name":"Rum","measure":"15 ml"},{"name":"Vodka","measure":"15 ml"},{"name":"Gin","measure":"15 ml"},{"name":"Tequila","measure":"15 ml"},{"name":"Licor de Curaçau Blue","measure":"15 ml"},{"name":"Energético","measure":"completar"}]', '["Encha um copo highball com gelo coloque o Curaçau Blue, o Rum, a Vodka, o Gin e a Tequila, complete com Energético."]', '', 'Montado', 'Alcoólico', '/uploads/recipes/Bullfrog.png'),
