('Guadalupi', '', '[{"name":"Tequila","measure":"50 ml"},{"name":"Licor de Curaçau Blue","measure":"20 ml"},{"name":"Licor de Curaçau Red","measure":"10 ml"},{"name":"Soda Limonada","measure":"completar"}]', '["Encha um copo highball com gelo, coloque o Licor de Curaçau Red, a Tequila, o Curaçau Blue, complete com Soda Limonada."]', '', 'Montado', 'Alcoólico', '/uploads/recipes/Guadalupi.jpg'),
('Chacal', '', '[{"name":"Rum","measure":"50 ml"},{"name":"Suco de Cranberry","measure":"40 ml"},{"name":"Suco de Limão","measure":"20 ml"},{"name":"Fanta","measure":"completar"}]', '["Encha um copo highball com gelo, coloque o Rum, o Suco de Cranberry e o de Limão. Complete com a fanta Laranja."]', '', 'Montado', 'Alcoólico', '/uploads/recipes/Chacal.png'),
('Slow Release', '', '[{"name":"Rum Blanco","measure":"30 ml"},{"name":"Rum Malibu","measure":"20 ml"},{"name":"Suco de Limão","measure":"30 ml"},{"name":"Xarope de Alecrim","measure":"20 ml"},{"name":"Soda Limonada","measure":"completar"}]', '["Coloque todos os ingredientes em um copo rocks com gelo. Complete com a Soda Limonada. Mexa com a bailarina. Use um ramo de alecrim como guarnição e raspas de Limão.","Coloque duas rodelas bem finas de Limão no fundo do copo, antes de colocar o gelo."]', '', 'Montado', 'Alcoólico', '/uploads/recipes/Slow_Release.jpg'),
('Mango Mimosa', '', '[{"name":"Suco de Manga","measure":"75 ml"},{"name":"Moscatel, Espumante","measure":"completar"}]', '["Coloque todos os ingredientes em uma taça flute, use o espumante de sua preferencia."]', '4-5 Blueberries', 'Montado', 'Alcoólico', '/uploads/recipes/Mango_Mimosa.jpg'),
