('Jack\''N\''Blue', '', '[{"name":"Whiskey Jack Daniel’s","measure":"50 ml"},{"name":"Licor de Curaçau Blue","measure":"50 ml"},{"name":"Soda Limonada","measure":"completar"}]', '["Encha um copo highball com gelo. Coloque o Curaçau, a soda, e por último com auxílio da bailarina o jack."]', '', 'Montado', 'Alcoólico', '/uploads/recipes/Jack-n-Blue.jpg'),
('Acid Green', '', '[{"name":"Vodka","measure":"60 ml"},{"name":"Xarope de Maçã Verde","measure":"30 ml"},{"name":"Suco de Limão","measure":"2 unidades"}]', '["Encha um copo highball com gelo, coloque o xarope, a Vodka (misture), e complete com o Suco de Limão.","*OBSERVAÇÃO: nesse caso fazer o Suco de Limão no liquidificador, retire as sementes, coloque no liquidificador com Água e bata bem. Coe."]', '', 'Montado', 'Alcoólico', '/uploads/recipes/Acid_Green.png'),
