('Malibu Sunset', '', '[{"name":"Rum Malibu","measure":"25 ml"},{"name":"Suco de Abacaxi","measure":"50 ml"},{"name":"Xarope de Grenadine","measure":"3 colheres de bar"}]', '["Encha um copo com cubos de gelo.","Despeje o Abacaxi e o Rum Malibu sobre os cubos de gelo, despeje o Xarope ou o Xarope de Grenadine lentamente em um lado do copo.","Decore com Cerejas / Abacaxi, se desejar."]', 'Cerejas / fatias de Abacaxi', 'Montado', 'Alcoólico', '/uploads/recipes/Malibu_Sunset.png'),
('Green Beats', '', '[{"name":"Vodka","measure":"50 ml"},{"name":"Licor de Curaçau Blue","measure":"50 ml"},{"name":"Suco de Laranja","measure":"100 ml"},{"name":"Skol Beats GT","measure":"completar"}]', '["Num copo com gelo, adicione o Suco de Laranja, Vodka, e delicadamente vai colocando o Curaçau Blue, depois é só completar com a skol."]', '', 'Montado', 'Alcoólico', '/uploads/recipes/Green_beats.png'),
('Vinho Tônica', '', '[{"name":"Gin","measure":"30 ml"},{"name":"Água Tônica","measure":"150 ml"},{"name":"Vinho Tinto Suave","measure":"50 ml"}]', '["Em uma taça de Vinho tinto cheia de gelo adicione o Gin e a tônica e com uma colher bailarina mexa suavemente.","Despeje o Vinho suavemente com auxílio da colher bailarina para que o Vinho fique por cima."]', '', 'Montado', 'Alcoólico', '/uploads/recipes/Vinho_Tonica.png'),
('Halloween Sunrise', '', '[{"name":"Vodka (corante comestível preto)","measure":"30 ml"},{"name":"Xarope de Grenadine","measure":"7,5 ml"},{"name":"Suco de Laranja","measure":"100 ml"}]', '["Encher um copo com gelo e servir o Suco de Laranja. Servir pela lateral do copo e devagar o Xarope de Grenadine.","Com as costas de uma colher, servir lentamente a Vodka.","Guarnecer com um pedaço de alcaçuz (Licorice)."]', 'um pedaço de alcaçuz', 'Montado', 'Alcoólico', '/uploads/recipes/Halloween_Sunrise.jpg'),
('Mojito de Jurupinga', '', '[{"name":"Jurupinga","measure":""},{"name":"Água com Gás","measure":"50 ml"},{"name":"Hortelã","measure":"10 folhas"},{"name":"Açúcar","measure":"1 colher de bar"},{"name":"Suco de Limão","measure":"1 unidade"}]', '["Em um copo alto, macerar a Hortelã, o Açúcar e o Limão","Adicionar Jurupinga até a metade, adicionar a Água com Gás","Completar com gelo, e decorar com pedacinhos de Limão, Hortelã e um canudo"]', 'Pedacinhos de Limão e folhas de Hortelã', 'Montado', 'Alcoólico', '/uploads/recipes/Mojito_de_Jurupinga.jpg'),
