('Golden Peach', '', '[{"name":"Gin","measure":"45 ml"},{"name":"Licor de Pêssego","measure":"45 ml"},{"name":"Suco de Pêssego","measure":"120 ml"},{"name":"Xarope de Grenadine","measure":"Dash"}]', '["Combine todos os ingredientes, exceto para as fatias de Pêssego, em copo alto cheio de cubos de gelo.","Mexa com uma colher de mistura. Enfeite com rodelas de Pêssego."]', 'Fatias de Pêssego', 'Montado', 'Alcoólico', '/uploads/recipes/Golden_Peach.png'),
