('Black Sunrise', '', '[{"name":"Tequila Blanco","measure":"45 ml"},{"name":"Suco de Laranja","measure":"90 ml"},{"name":"Xarope de Grenadine","measure":"15 ml"},{"name":"Xarope Gum Nero ou corante preto na Tequila","measure":"10 ml"}]', '["Construir em um copo com gelo."]', '', 'Montado', 'Alcoólico', '/uploads/recipes/BLACK_SUNRISE.png'),
('Strawberry Mint Sparkler', '', '[{"name":"Vodka","measure":"60 ml"},{"name":"Xarope de Açúcar","measure":"15 ml"},{"name":"Suco de Limão","measure":"15 ml"},{"name":"Morangos","measure":"5 unidades"},{"name":"Hortelã","measure":"10 folhas"},{"name":"Soda Limonada","measure":"completar"}]', '["Em uma coqueteleira, misture os Morangos fatiados, Xarope de Açúcar e Suco de Limão e bata até que os Morangos sejam completamente dissolvidos.","Adicione folhas Hortelã e macere suavemente mais 5 vezes. (Não macere demais a Hortelã) Adicione Vodka a coqueteleira e encha 2/3 de gelo.","Agite até ficar bem frio, cerca de 15 segundos. Encha um copo collins com gelo e adicione refrigerante."]', 'Roda de Limão, Hortelã ou Morango', 'Montado', 'Alcoólico', '/uploads/recipes/Strawberry_Mint_Sparkler.jpg'),
('Fruit Cup', '', '[{"name":"Gin","measure":"25 ml"},{"name":"Licor de Curaçau Blue","measure":"25 ml"},{"name":"Vermute Rosso (Doce)","measure":"25 ml"},{"name":"Angostura Aromatic Bitters","measure":"2 dashes"},{"name":"Ginger Ale","measure":"50 ml"}]', '["Construir em um copo long com gelo."]', '', 'Montado', 'Alcoólico', '/uploads/recipes/Fruit_Cup.png'),
('Harvard Cooler', '', '[{"name":"Conhaque","measure":"60 ml"},{"name":"Suco de Limão","measure":"30 ml"},{"name":"Xarope de Açúcar","measure":"15 ml"},{"name":"Soda Limonada","measure":"completar"}]', '["Combine todos os ingredientes em um copo longo com gelo, menos a soda que é para completar. Obs.: O xarope de açúcar é 2:1."]', '', 'Montado', 'Alcoólico', '/uploads/recipes/Harvard_Cooler.png'),
('Belvedere Ginger Spritz', '', '[{"name":"Vodka","measure":"30 ml"},{"name":"Vermute Rosso (Doce)","measure":"30 ml"},{"name":"Gengibre","measure":"1 fatia"},{"name":"Laranja","measure":"2 fatias"},{"name":"Água com Gás","measure":""},{"name":"Água Tônica","measure":""}]', '["Combine todos os ingredientes em uma taça de spritz de belvedere, cheia de gelo, cubra com partes iguais de Água com Gás e Água Tônica."]', '', 'Montado', 'Alcoólico', '/uploads/recipes/BELVEDERE_GINGER_SPRITZ.png'),
('Chá do Alasca', '', '[{"name":"Vodka","measure":"50 ml"},{"name":"Licor de Curaçau Blue","measure":"25 ml"},{"name":"Suco de Limão","measure":"½ unidade"},{"name":"Sprite","measure":"completar"},{"name":"Gelo de Água de Coco","measure":""}]', '["Comece preenchendo o copo com gelo de coco. Adicione o Curaçau Blue e em seguida o Suco do meio Limão. Acrescente a Vodka e para finalizar complete com o sprite. Decore como quiser e sirva!!"]', '', 'Montado', 'Alcoólico', '/uploads/recipes/Cha_do_Alasca.png'),
('Pokas Ideia', '', '[{"name":"Gin","measure":"50 ml"},{"name":"Mel","measure":"30 ml"},{"name":"Suco Limão Siciliano","measure":"½ unidade"},{"name":"Morango","measure":"1 unidade"}]', '["Na coqueteleira coloque o Morango, o mel e macere bem para deixar somente a Polpa do Morango, acrescentar o Suco do Limão, 3 pedras de gelo e o Gin. bater bastante. ","Completo o copo que vai receber o drink com bastante gelo, despeje o líquido nesse copo."]', 'Ramo Hortelã', 'Batido', 'Alcoólico', '/uploads/recipes/pokas_ideia.PNG'),
('Maracu Jack', '', '[{"name":"Jack Daniel’s","measure":"50 ml"},{"name":"Jack Daniel’s Honey","measure":"25 ml"},{"name":"Suco de Limão","measure":"½ unidade"},{"name":"Polpa de Maracujá","measure":"1 unidade"},{"name":"Suco de Maracujá","measure":"completar"}]', '["Em um copo longo adicione o Jack Daniel’s, o Jack Daniel’s honey e o Suco do Limão.","Complete o copo com gelo. De uma boa mexida para dar uma boa gelada.","Complete o copo com Suco de Maracujá bem gelado!!!","Adicione duas colheres de pompa de Maracujá, e mecha novamente."]', '', 'Montado', 'Alcoólico', '/uploads/recipes/MARACU_JACK.jpg'),
('Rainbow Drink', '', '[{"name":"Vodka","measure":"70 ml"},{"name":"Groselha","measure":"50 ml"},{"name":"Licor de Curaçau Blue","measure":"50 ml"},{"name":"Suco de Laranja","measure":"150 ml"}]', '["Encher o copo com gelo, colocar o Suco de Laranja, acrescentar a Groselha bem no cantinho do copo para ir lá para o fundo, colocar a Vodka e por último o Curaçau Blue também no canto do copo."]', '', 'Montado', 'Alcoólico', '/uploads/recipes/rainbow_drink.PNG'),
('Chamomile Honey Syrup', '', '[{"name":"Tequila","measure":"60 ml"},{"name":"Suco de Toranja (Grapefruit)","measure":"90 ml"},{"name":"Xarope de Camomila","measure":"4 colheres de bar"},{"name":"Morangos","measure":"4 unidades"},{"name":"Água com Gás","measure":"completar"}]', '["Adicione o Suco de toranja, o Xarope de camomila, a Tequila e os Morangos fatiados em um copo. Macere suavemente os Morangos até que eles liberem seus sucos e sejam ligeiramente esmagados.","Adicione um punhado de gelo e, em seguida, adicione Água com Gás para completar.","Dê uma mexida suave na bebida. Prove e adicione mais Xarope de camomila, se desejar. Enfeite com flores de camomila frescas e Morangos."]', 'flores de camomila frescas e Morangos', 'Montado', 'Alcoólico', '/uploads/recipes/CHAMOMILE_HONEY_SYRUP.png'),
('Americano', '', '[{"name":"Vermute Rosso (Doce)","measure":"30 ml"},{"name":"Campari","measure":"30 ml"},{"name":"Club Soda","measure":"completar"}]', '["Adicione o vermute e o Campari em um copo baixo com gelo, complete com o Club Soda e mexa bem."]', '', 'Montado', 'Alcoólico', '/uploads/recipes/americano.png'),
('Virgin Pussy Foot', '', '[{"name":"Xarope de Grenadine","measure":"20 ml"},{"name":"Suco de Limão","measure":"20 ml"},{"name":"Suco de Laranja","measure":"completar"}]', '["Complete um copo longo com o Suco de Laranja e misture o Suco de Limão. Depois adicione o Xarope de Grenadine e decore com Cerejas e rodelas de Laranja."]', 'Cerejas e rodelas de Laranja', 'Montado', 'Sem Álcool', '/uploads/recipes/VIRGIN_PUSSY_FOOT.jpg'),
('Blue Crush Margarita', '', '[{"name":"Tequila","measure":"60 ml"},{"name":"Cointreau (Triple Sec)","measure":"15 ml"},{"name":"Xarope Curaçau Blue","measure":"30 ml"},{"name":"Suco de Limão","measure":"15 ml"},{"name":"Club Soda","measure":"completar"}]', '["Passar Limão na borda e depois mergulhe no sal, encher o copo com gelo, despeje todos os ingredientes no copo menos o Club Soda, de uma mexida e complete com o Club Soda. Decore com meia rodela de Limão."]', 'meia rodela de Limão', 'Montado', 'Alcoólico', '/uploads/recipes/Blue_Crush_Margarita.png'),
('Jack Honey Blackberry', '', '[{"name":"Jack Daniels Honey","measure":"50 ml"},{"name":"Suco de Limão Siciliano","measure":"25 ml"},{"name":"Xarope de Gengibre","measure":"20 ml"},{"name":"Soda Limonada","measure":"150 ml"},{"name":"Chá de Frutas Vermelhas","measure":"1 unidade"}]', '["Só colocar todos os ingredientes em uma caneca grande ou copo longo. Bastante gelo e misturar bem."]', '', 'Montado', 'Alcoólico', '/uploads/recipes/JACK_HONEY_BLACKBERRY.jpg'),
('Purple Season', '', '[{"name":"Skol Beats 150 bpm","measure":"1 unidade"},{"name":"Suco de Limão","measure":"20 ml"},{"name":"Água Tônica","measure":"completar"},{"name":"Gelo de Água de Coco","measure":""}]', '["Numa taça com gelo de côco, adicione o Suco de Limão, a skol, complete com Água Tônica e coloque os limões nas laterais e decore."]', '2 fatias Limão nas laterais do copo', 'Montado', 'Alcoólico', '/uploads/recipes/PURPLE_SEASON.jpg'),
('Mula Sem Cabeça', '', '[{"name":"Cachaça","measure":"50 ml"},{"name":"Suco de Limão","measure":"1/2 Unidade"},{"name":"Xarope de Gengibre","measure":"25 ml"},{"name":"Xarope de Mel","measure":"25 ml"},{"name":"Água com Gás","measure":"completar"}]', '["Misture, e complete com Água com Gás. Finalize com espuma de gengibre, Hortelã e raspa de Limão."]', 'Hortelã e raspa de Limão', 'Montado', 'Alcoólico', '/uploads/recipes/MULA_SEM_CABECA.png'),
('Orange Gin', '', '[{"name":"Gin","measure":"50 ml"},{"name":"Suco de Limão","measure":"1/2 unidade"},{"name":"Energético Khaos","measure":"completar"}]', '["Adicione gelo em uma taça de Gin. Coloque o Gin, o Suco do Limão. Mexa bem para gelar a mistura e soltar a essência da especiaria.","Complete a taça com gelo e posicione a fatia de Laranja Bahia na extremidade da taça. Por último adicione o Monster Juice, e de uma mexida de leve."]', 'Fatia Laranja Bahia', 'Montado', 'Alcoólico', '/uploads/recipes/ORANGE_GIN.jpg'),
('Carpe Drink', '', '[{"name":"Amoras","measure":"12 unidades"},{"name":"Suco de Limão","measure":"30 ml"},{"name":"Xarope de Açúcar","measure":"25 ml"},{"name":"Blueberry","measure":"5 unidades"},{"name":"Skol Beats Zodiac Elemento Ar","measure":"completar"}]', '["Macerar as amoras com o Suco de Limão e o xarope. Colocar em um copo com gelo, completar com a Skol Beats, misturar e acrescentar Blueberries."]', 'Fatia Laranja Desidratada', 'Montado', 'Alcoólico', '/uploads/recipes/Carpe_Drink.png'),
('Apple Orchard Fizz', '', '[{"name":"Vodka Absolut Juice Apple","measure":"30 ml"},{"name":"Suco de Laranja","measure":"15 ml"},{"name":"Soda Limonada","measure":"completar"}]', '["Encher um copo alto com gelo. Adicionar todos os ingredientes. Decorar com Limão."]', '1 pedaço de Limão (guarnição)', 'Montado', 'Alcoólico', '/uploads/recipes/Apple_Orchard_Fizz.jpg'),
('Absolut Orange Juice', '', '[{"name":"Vodka","measure":"45 ml"},{"name":"Suco de Laranja","measure":"completar"}]', '["Encher um copo alto com cubos de gelo. Adicionar todos os ingredientes. Decorar com Laranja."]', 'Laranja (guarnição)', 'Montado', 'Alcoólico', '/uploads/recipes/Absolut_Orange_Juice.png'),
('Whiskey Soda', '', '[{"name":"Whiskey","measure":"60 ml"},{"name":"Soda Limonada","measure":"completar"}]', '["Misture todos os ingredientes."]', 'Folhas Hortelã', 'Montado', 'Alcoólico', '/uploads/recipes/WHISKY_SODA_II.jpg'),
('Matte com Whiskey', '', '[{"name":"Whiskey","measure":"50 ml"},{"name":"Chá Mate","measure":"200 ml"},{"name":"Suco de Limão","measure":"1/2 unidade"},{"name":"Açúcar","measure":"2 colheres de bar"}]', '["Misture todos os ingredientes em um copo e finalize colocando o gelo."]', '', 'Montado', 'Alcoólico', '/uploads/recipes/Matte_com_whisky.png'),
('Gin da Sorte', '', '[{"name":"Gin","measure":"50 ml"},{"name":"Xarope de Framboesa","measure":"20 ml"},{"name":"Romã","measure":"1/2 unidade"},{"name":"Água Tônica Rosé","measure":"completar"}]', '["Em uma taça de Gin com gelo pela metade adicione o Gin, o Xarope de framboesa, e 1/4 de sementes de uma Romã.","De uma boa misturada para homogeneizar, gelar.","Complete a taça com gelo e complete o copo com Água Tônica rose.","Cubra o gelo com mais 1/4 das sementes de Romã."]', '', 'Montado', 'Alcoólico', '/uploads/recipes/GIN_SORTE.png'),
('Tequila Citrus', '', '[{"name":"Tequila Reposado","measure":"50 ml"},{"name":"Suco de Limão","measure":"15 ml"},{"name":"Sal","measure":"1 pitada"},{"name":"Schweppes Citrus","measure":"completar"}]', '["Misture todos os ingredientes em um copo. Gelo a gosto."]', '', 'Montado', 'Alcoólico', '/uploads/recipes/Tequila_Citrus.png'),
('Sakai', '', '[{"name":"Sakai","measure":"120 ml"},{"name":"Morangos","measure":"3 unidades"},{"name":"Açúcar","measure":"1 colher de bar"}]', '["Em uma taça ou copo bata os Morangos fatiados junto com o Açúcar, acione o gelo e 3 ou 4 doses de Sakai.","Por último coloque as folhas Hortelã."]', 'Folhas de hortelã', 'Montado', 'Alcoólico', '/uploads/recipes/Sakai.png'),
('Gin Coconut Blades', '', '[{"name":"Gin","measure":"50 ml"},{"name":"Corote Blueberry (Azul)","measure":"30 ml"},{"name":"Suco de Limão","measure":"20 ml"},{"name":"Schweppes Citrus","measure":"completar"}]', '["Em uma taça vá adicionando o Gin, o Corote de Blueberry e o Suco do Limão, adicione gelo pela metade da taça e de uma boa mexida para gelar, complete a taça com gelo e posicione o coco desidratado nas extremidades da taça, complete a taça com gelo.","Finalize com Pimenta Rosa sobre o Drink, mexa novamente de leve e decore com o Ramo de alecrim parcialmente queimado."]', 'Lâminas de Coco Branco e Ramo de alecrim', 'Montado', 'Alcoólico', '/uploads/recipes/GIN_COCONUT_BLADES.png'),
('Moscow Mule - Versão Original', '', '[{"name":"Vodka","measure":"50 ml"},{"name":"Ginger Beer","measure":"100 ml"},{"name":"Suco de Limão","measure":"20 ml"}]', '["Diretamente na caneca de cobre com bastante gelo, junte os ingredientes e misture levemente. Decore e perfume com Limão e Hortelã."]', '', 'Montado', 'Alcoólico', '/uploads/recipes/Moscow_Mule_-_Vers__o_Original.png'),
('Lagoa Encantada', '', '[{"name":"Vodka","measure":"25 ml"},{"name":"Xarope de Groselha","measure":"17 ml"},{"name":"Licor Curaçau Blue","measure":"25 ml"},{"name":"Suco de Limão","measure":"1 unidade"},{"name":"Jurupinga","measure":"completar"},{"name":"Licor de Curaçau Blue","measure":"17 ml"}]', '["Em um copo longo, adicione gelo, o Suco do Limão, o Xarope de Groselha, dê uma leve mexida, acrescente a primeira medida de Licor de Curaçau Blue, complete com a Jurupinga, mas deixe uns 2 dedos da borda do copo, mexa novamente.","Adicione a Vodka com as costas da colher bailarina e acrescenta por final a outra medida do Curaçau Blue, também pelas costas da colher para não mistura e sim ficar próximo a bordo do copo e dê outra mexida de leve na parte de cima do copo para misturar a"]', 'Ramo Hortelã e Mirtilo', 'Montado', 'Alcoólico', '/uploads/recipes/Lagoa_Encantada.JPG'),
('Tropical Label', '', '[{"name":"Whiskey","measure":"50 ml"},{"name":"Suco de Limão","measure":"1/2 unidade"},{"name":"Polpa de Maracujá","measure":"2 colher de bar"},{"name":"Energético Tropical","measure":"completar"}]', '["Em um copo grande, adicione gelo, o Suco do Limão, o Whiskey, 1 colher da polpa do maracujá, misture bem, completar com o Energético Tropical (bem gelado), coloque um ramo de manjericão dentro do copo e dê uma misturada novamente. Complete com gelo tritur"]', 'Ramo de manjericão', 'Montado', 'Alcoólico', '/uploads/recipes/tropical_label.JPG'),
('Purple Skull', '', '[{"name":"Vodka","measure":"25 ml"},{"name":"Skol Beats 150 bpm","measure":"1 unidade"},{"name":"Energético Monster Violet","measure":"completar"}]', '["Acrescente todos os ingredientes num copo de caveira ou taça, decore a borda a gosto."]', '', 'Montado', 'Alcoólico', '/uploads/recipes/PURPLE_SKULL.jpg'),
('Maracujá Ice', '', '[{"name":"Leite Condensado","measure":"50 ml"},{"name":"Vodka","measure":"50 ml"},{"name":"Maracujá","measure":"1 unidade"},{"name":"Ice Smirnoff","measure":"completar"}]', '["Misture todos os ingredientes numa taça de Gin."]', '', 'Montado', 'Alcoólico', '/uploads/recipes/MARACUJA_ICE.png'),
('Corona Sunrise', '', '[{"name":"Cerveja Corona","measure":"1 unidade"},{"name":"Tequila","measure":"50 ml"},{"name":"Suco de Laranja","measure":"50 ml"},{"name":"Xarope de Grenadine","measure":"20 ml"}]', '["Fazer dentro da garrafa, tirar uns 120 ml do conteúdo da garrafa.","Vire lentamente a Tequila, Suco de Laranja e por último o Xarope de Grenadine. Finalize com uma fatia de Limão."]', 'fatia de Limão dentro da garrafa', 'Montado', 'Alcoólico', '/uploads/recipes/Corona_Sunrise.jpg'),
('150 BPM Ice', '', '[{"name":"Skol Beats 150 BPM","measure":"100 ml"},{"name":"Suco de Limão","measure":"15 ml"},{"name":"Ice Smirnoff","measure":"completar"}]', '["Em uma taça de sua preferência, adicione a Skol Beats 150 BPM bem gelada, e o Suco de Limão.","Complete a taça com gelo e de uma boa mexida.","Complete com Smirnoff Ice."]', '', 'Montado', 'Alcoólico', '/uploads/recipes/150_BPM_ICE.png'),
('Victory Collins', '', '[{"name":"Vodka","measure":"45 ml"},{"name":"Suco de Limão","measure":"90 ml"},{"name":"Suco de Uva","measure":"90 ml"},{"name":"Laranja","measure":"1 fatia"},{"name":"Açúcar","measure":"1 colher de bar"}]', '["Misturar todos os ingredientes num copo alto e mexer."]', '', 'Montado', 'Alcoólico', '/uploads/recipes/Victory_Collins.jpg'),
('King of Orange', '', '[{"name":"Vodka","measure":"40 ml"},{"name":"Licor Grand Marnier (ver Grand Marnier)","measure":"20 ml"},{"name":"Campari","measure":"7,5 ml"},{"name":"Suco de Limão","measure":"10 ml"},{"name":"Prosecco, Espumante","measure":"25 ml"}]', '["Coloque todos os ingredientes gelados numa taça de espumante."]', '', 'Batido', 'Alcoólico', '/uploads/recipes/king_of_orange.jpg'),
('Trick Or Gin', '', '[{"name":"Gin","measure":"50 ml"},{"name":"Energético de açaí","measure":"90 ml"},{"name":"Limão Siciliano","measure":"15 ml"},{"name":"Limão","measure":"15 ml"},{"name":"Cointreau (Triple Sec)","measure":"15 ml"},{"name":"Glitter comestível Prata","measure":""}]', '["Em um copo baixo de sua preferência, adicione todos os ingredientes com gelo."]', 'Uma fatia de Laranja seca', 'Montado', 'Alcoólico', '/uploads/recipes/Trick_or_GIN.jpg'),
('Tequila com Cerveja', '', '[{"name":"Tequila","measure":"60 ml"},{"name":"Cerveja Pilsen","measure":"60 ml"},{"name":"Limonada Concentrada","measure":"60 ml"},{"name":"Água sem gás","measure":"60 ml"}]', '["Misture os ingredientes na coqueteleira. Finalize enfeitando com Limão e sal o copo."]', 'Limão e sal no copo', 'Montado', 'Alcoólico', '/uploads/recipes/Tequila_com_Cerveja.png'),
('Bitter Mai Tai', '', '[{"name":"Campari","measure":"45 ml"},{"name":"22,5 ml Jamaican Rum","measure":""},{"name":"Licor de Laranja","measure":"15 ml"},{"name":"Suco de Limão","measure":"30 ml"},{"name":"22,5 ml Orgeat","measure":""}]', '["Em um copo baixo de sua preferência, adicione todos os ingredientes com gelo. Guarnição ramo Hortelã."]', 'ramo Hortelã', 'Montado', 'Alcoólico', '/uploads/recipes/Bitter_Mai_Tai.png'),
('Piscininha Amor', '', '[{"name":"Xarope de Curaçau Blue","measure":"15 ml"},{"name":"Brütt, Espumante","measure":"completar"}]', '["Em uma taça flute, adicione o xarope, e depois complete com o espumante, finalize com a meia rodela de laranja."]', 'Meia rodela de laranja', 'Montado', 'Alcoólico', '/uploads/recipes/PISCININHA_AMOR.jpg'),
('Lynchburg Lemonade', 'A limonada lynchburg leva o nome da cidade natal da destilaria Jack Daniel’s, no Tennessee. \nÉ uma das bebidas mistas mais populares em que harmonizamos o whisky com limonada! ', '[{"name":"Whiskey Jack Daniels","measure":"50 ml"},{"name":"Cointreau (Triple Sec)","measure":"50 ml"},{"name":"Sour Mix","measure":"50 ml"},{"name":"Sprite","measure":"completar"}]', '["Depois é só completar com refrigerante de limão e misturar bastante. Ao invés do sour mix, você pode substituir por suco de limão natural."]', '', 'Batido', 'Clássico', '/uploads/recipes/lynchburg-lemonade.jpg'),
('Bombeirinho', 'Mais um ícone dos coquetéis, o bombeirinho surgiu na década de 1980, época em que os ingredientes doces como groselhas, refrigerantes e leite condensado se popularizaram.', '[{"name":"Cachaça","measure":"30 ml"},{"name":"Suco de Limão","measure":"10 ml "},{"name":"Groselha","measure":"10 ml"}]', '["Coloque todos os ingredientes num copo mixing e misture. Coe para um copo baixo e sirva."]', '', 'Mexido', 'Alcoólico', '/uploads/recipes/Bombeirinho.jpg'),
('Corpse Reviver #2', 'É um coquetel seco e cítrico, uma versão super aromática de um White Lady, devido à baixa quantidade de Gim é também um coquetel com menor teor alcoólico e excelente como aperitivo.', '[{"name":"Gin","measure":"30 ml"},{"name":"Lillet Blanc ou Vinho Aperitivo","measure":"30 ml"},{"name":"Cointreau (Triple Sec)","measure":"30 ml "},{"name":"Suco de Limão Siciliano","measure":"30 ml"},{"name":"Absinto","measure":"5 gotas"}]', '["Bata todos os ingredientes com gelo e sirva com coagem dupla em taça resfriada. Decorar com casca de limão siciliano."]', 'Casca de limão siciliano', 'Batido', 'Alcoólico', '/uploads/recipes/corpse-reviver-2.jpg'),
('Vieux Carré', 'O Vieux Carré é um coquetel oficial da IBA feito com uísque de centeio, conhaque, vermute doce, Bénédictine e Peychaud\''s bitters. Originou-se com Walter Bergeron, um barman no Carousel Bar no Hotel Monteleone, New Orleans. O nome é francês para “praça velha”, em referência ao bairro French Quarter da cidade.', '[{"name":"Rye Whiskey","measure":"22,5 ml"},{"name":"Conhaque","measure":"22,5 ml"},{"name":"Vermute Rosso (Doce)","measure":"22,5 ml"},{"name":"Licor Bénédictine","measure":"2 colheres de bar"},{"name":"Angostura Aromatic Bitters","measure":"4 dashes"}]', '["Adicione o whiskey, conhaque, vermute doce, licor benedictine e bitters em um copo mixing glass com gelo e mexa até que fiquem bem gelados.","Coe em um copo com gelo ou um copo de coquetel."]', 'Cereja e Casca de limão torcida', 'Mexido', 'Alcoólico', '/uploads/recipes/vieux-carre.jpg'),
('Blue Blazer (original)', 'O Blue Blazer é um coquetel histórico e teatral criado por Jerry Thomas, caracterizado por ser incendiado e transferido entre duas canecas de metal, criando uma chama azul. Leva uísque escocês, água fervente e açúcar, resultando em um sabor defumado e intenso, servido com casca de limão.', '[{"name":"Whiskey Escocês","measure":"60 ml"},{"name":"Água Quente","measure":"60 ml"},{"name":"Xarope de Açúcar","measure":"10 ml"}]', '["Em duas leiteiras escaldadas adicione, separadamente, a água com xarope de açúcar e o whisky. Coloque fogo no destilado e faça um “dry throwing” deixando o whisky cair sobre a água.","Continue vertendo a mistura de uma leiteira para a outra mais quatro vezes. Apague o fogo colocando uma leiteira sobre a outra e sirva numa taça de conhaque. "]', 'Casca de limão siciliano.', 'Batido', 'Alcoólico', '/uploads/recipes/blue_blazer.jpg'),
('White Lady', 'Com uma história tenebrosa o White Lady, desta vez o coquetel, foi criado pelo bartender Harry MacElhone em 1919 no Ciro Club de Londres usando partes iguais de licor de menta, triple sec e suco de limão siciliano. Provavelmente esta receita de arrepiar era resquício dos tempos difíceis pós primeira guerra mundial.', '[{"name":"London Dry Gin","measure":"50 ml"},{"name":"Cointreau (Triple Sec)","measure":"25 ml"},{"name":"Suco de Limão Siciliano","measure":"25 ml"},{"name":"Clara de Ovo","measure":"30 ml"}]', '["Bater com gelo e servir com coagem dupla em uma taça previamente resfriada."]', '', 'Batido', 'Alcoólico', '/uploads/recipes/white_lady.jpg'),
('Tommy\''s Margarita', 'A Tommy\''s Margarita é uma releitura moderna e oficial da IBA (International Bartenders Association), criada nos anos 90 por Julio Bermejo em San Francisco, Califórnia. Ela se diferencia da clássica por eliminar o licor de laranja, utilizando néctar de agave para destacar o sabor da tequila.', '[{"name":"Tequila Reposado","measure":"60 ml"},{"name":"Suco de Limão Siciliano","measure":"30 ml"},{"name":"Xarope de Agave","measure":"15 ml"}]', '["Adicione a tequila, o suco de limão e o néctar de agave em uma coqueteleira.\\nAdicione bastante gelo e agite vigorosamente por cerca de 10-15 segundos para resfriar.","Faça uma dupla coagem para um copo baixo (rocks glass) cheio de gelo fresco."]', 'Rodela ou cunha de limão', 'Batido', 'Clássico', '/uploads/recipes/tommys-margarita.jpg'),
('Russian Spring Punch ', 'O Russian Spring Punch mistura vodka espumante e frutas. O termo Russian vem da vodka. O termo Spring Punch vem da mistura de vinho com frutas em jarras para servir muitas pessoas. Foi criando em Londres na década de 1980 pelo bartender Dick Bradsell.', '[{"name":"Vodka","measure":"50 ml"},{"name":"Xarope de Açúcar","measure":"15 ml"},{"name":"Suco de Limão Siciliano","measure":"20 ml"},{"name":"Licor de Framboesa","measure":"15 ml"},{"name":"Licor de Creme de Cassis","measure":"15 ml"},{"name":"Brütt, Espumante","measure":"completar"}]', '["Coloque todos os ingredientes em uma coqueteleira com gelo. Bata bem. Encha um copo longo com bastante gelo triturado.","Passe o conteúdo da coqueteleira com um strainer para o copo, complete com o espumante e mexa levemente e sirva com um canudo."]', '', 'Batido', 'Clássico', '/uploads/recipes/russian-spring-punch.jpg'),
('#Natal', '', '[{"name":"Suco de Limão Siciliano","measure":"10 ml"},{"name":"Licor Curaçau Blue","measure":"50 ml"},{"name":"Energético RB Blueberry e Baunilha","measure":"1 unidade"},{"name":"Sprite","measure":"completar"}]', '["Fazer a borda do copo, encher de gelo, acrescentar o suco do limão, coloque o licor, encha até a metade do copo com o energético","Depois para finalizar completo com o sprite."]', 'Leite condensado e coco ralado na borda', 'Montado', 'Alcoólico', '/uploads/recipes/_Natal.png'),
('Hi-Fi', 'A hi-fi é uma bebida alcoólica, ou um coquetel feito de vodka, refrigerante de laranja e gelo.\nO nome é inspirado no nome do programa \"Crush em Hi-Fi\", exibido no Brasil no início dos anos 60. \"Crush\" é o nome de um refrigerante de laranja, patrocinador do programa. Não confundir com o Screwdriver, que é feito com suco de laranja. Em algumas variações, pode-se substituir a vodka por cachaça.', '[{"name":"Vodka","measure":"60 ml"},{"name":"Fanta","measure":"completar"}]', '["Num copo alto com bastante gelo, coloque a vodka e depois completa com a fanta."]', 'Meia laranja', 'Montado', 'Alcoólico', '/uploads/recipes/hi-fi.jpg'),
('Martini Paradise', '', '[{"name":"Rum Ouro","measure":"25 ml"},{"name":"Xarope de Grenadine","measure":"25 ml"},{"name":"Suco de Laranja","measure":"50 ml"},{"name":"Suco de Abacaxi","measure":"25 ml"},{"name":"Licor Curaçau Blue","measure":"25 ml"}]', '["Em uma taça de martini: acrescente gelo triturado até metade, grenadine, suco de laranja e o suco de abacaxi.","Misturar separado, em um copo de dose, o rum oro e o curaçau blue.","Colocar a bebida por cima usando uma colher.","Decorar com um morango na borda e um ramo de hortelã na borda."]', 'Morango e ramo de hortelã', 'Montado', 'Alcoólico', '/uploads/recipes/MARTINI_PARADISE.jpg'),
('Mexican Mule', '', '[{"name":"Tequila Blanco ou Prata","measure":"60 ml"},{"name":"Suco de Limão","measure":"30 ml"},{"name":"Ginger Beer (ver Cerveja de Gengibre )","measure":"completar"}]', '["Acrescente os ingredientes em uma caneca de cobre, e finalize com a guarnição."]', 'Ramo hortelã e cunha limão', 'Montado', 'Alcoólico', '/uploads/recipes/Mexican-Mule.jpg'),
('Green Phantom', '', '[{"name":"Xarope de Curaçau Blue","measure":"15 ml"},{"name":"Xarope de Maracujá","measure":"10 ml"},{"name":"Suco de Limão","measure":"5 ml"},{"name":"Energético Monster Ultra","measure":"completar"},{"name":"Polpa de Maracujá","measure":"1/2 unidade"}]', '["Coloque o gelo na coqueteleira, os xaropes, suco do limão e a polpa de meio maracujá.","Bate tudo, depois passe para um copo alto com gelo picado, e complete com o energético."]', 'Fatia de limão e maracujá', 'Batido', 'Sem Álcool', '/uploads/recipes/green-phantom.png')
